function lifeGuide(){openModal('Your partner’s lives',`<div class="life-guide"><span class="lives" aria-label="Three original lives">◆ ◆ ◆</span><p>Filled diamonds below HP show lives remaining. Each lethal defeat empties one.</p><p>Your original starter returns after the round at 10% HP while a life remains. Losing the final life is permanent. Other Abyssals begin with one life. Rare Life Embers can add a life to a living partner. The Civeton memorial can resurrect a permanent loss at the cost of 10 living partners of different species for its first revival, 12 for its second, 14 for its third, and two more each time.</p><button id="life-understood" class="primary">Understood</button></div>`);$('#life-understood').onclick=()=>{state.deathExplained=true;persist();closeModal();};}
async function showLifeNotices(){while(state.lifeNotices.length){const notice=state.lifeNotices[0];await new Promise(resolve=>{openModal(notice.dead?'Your partner is permanently lost':'Your partner lost a life',`<div class="life-guide"><h3>${escapeHTML(notice.name)}</h3><span class="lives" aria-label="${notice.lives} lives remaining">${'◆ '.repeat(notice.lives)}${'◇ '.repeat(Math.max(0,(notice.capacity||3)-notice.lives))}</span><p>${notice.dead?'The last pip has emptied. This partner is permanently lost from your expedition. The Civeton memorial can offer a costly resurrection.':`One pip has emptied. ${notice.lives} ${notice.lives===1?'life remains':'lives remain'}. Your partner has returned at 10% HP; the final loss will be permanent.`}</p><button id="life-understood" class="primary">Understood</button></div>`,()=>{state.lifeNotices.shift();persist();resolve();});$('#life-understood').onclick=closeModal;});}}

function interact(id){if(!state.begun||state.wiped||battle||dialogue||modal||presentationLocked)return;if(({'aldren':'LDR-01','yselle':'LDR-02','cybressa-provost':'LDR-03','cs-warden-local':'LDR-04','cs-warden':'LDR-04'})[id]&&state.fates?.[({'aldren':'LDR-01','yselle':'LDR-02','cybressa-provost':'LDR-03','cs-warden-local':'LDR-04','cs-warden':'LDR-04'})[id]]==='SPARED'){leaderRematchMenu();return;}if(id.startsWith('revolt-')){revoltInteract(id);return;}if(finaleInteract(id))return;if(botruneInteract(id))return;if(marasenInteract(id))return;if(cossenneInteract(id))return;if(mountainQuestInteract(id))return;if(id.startsWith('pass-')&&PASS_NPCS[id]){const n=PASS_NPCS[id];showDialogue(n.text.map(text=>line(n.name,text,id)));return;}if(courtInteract(id))return;if(LIFE_EMBER_PICKUPS.some(p=>p.id===id&&p.room===room)){let claimed=false;if(!rewardTransaction(()=>{claimed=claimLifeEmber(state,id);})||!claimed)return;buildMarkers();toast('Found Life Ember × 1 · adds one life to a living partner');return;}if(TRAVEL_HUBS.some(h=>h.id===id&&h.room===room)){fastTravelMenu();return;}if(id==='party-companion'){companionConversation();return;}if(id===jettyFor(room)?.id){jettyFishingMenu();return;}if(sideCampaignInteract(id))return;if(expansionInteract(id))return;const resident=residents.find(n=>n.id===id);if(resident){if(resident.id==='pate-mother'){showDialogue([line(resident.label,'Pate left before dawn. He barely touched his breakfast. He had already claimed a real Abyssal. I thought he had told you.'),line('Aimon','He said we would go together. He promised.','CHR-AIMON'),line(resident.label,'I know, love. He and Trade went with the column. I cannot tell you why they chose not to wake you. Speak to Trade’s family; perhaps he left you something.')],()=>{state.pate=true;refresh();toast('Journal updated · Pate left before dawn');});}else if(resident.id==='trade-grandfather'){showDialogue([line(resident.label,state.trade?'You still have the note, lad. I wish he had left you more than four words.':'Trade asked me to give you this. Said it was for you, and nobody else. He left with Pate before the bells.'),line(resident.label,state.trade?'He was very firm about leaving it with me.':'Here. Take it. I have not opened it.'),line('Trade’s note','“Don’t follow us.”'),line('Aimon','No explanation. No goodbye. Just an order. I’m not staying here.','CHR-AIMON')],()=>{state.trade=true;refresh();toast('Received Trade’s note');});}else showDialogue(resident.talk.map(text=>line(resident.label,text)));return;}const gate=AREA_GATES[room]?.find(g=>g.id===id);if(gate?.to&&!gate.action){void warp(gate.to,...gate.arrival);return;}if(id==='scrub-boundary'){scrubBoundary();return;}if(id==='bystander'){tamingDialogue();return;}if(id==='route-sign'){routeGuide();return;}if(id==='route-forward'){routeEnd();return;}if(id==='room-exit'){exitRoom();return;}if(DOORS[id]&&(DOORS[id].room||'town')===room){enterRoom(id);return;}blip();switch(id){
 case 'pate':showDialogue([line('Pate’s home','An unfinished breakfast. His mother is still here; you should ask her where he has gone.')]);break;
 case 'trade':showDialogue([line('Trade’s home',state.trade?'The desk is empty. You have the note his grandfather gave you.':'There is no note on the desk. Trade’s grandfather is waiting to speak to you.')]);break;
 case 'kurg':
  if(!state.pate||!state.trade){showDialogue([line('General William de Montfort','Pate and Trade have already left. Go and look at what they left for you before you make demands of me.','CHR-KURG')]);break;}
  if(state.starter||state.starterChosen){showDialogue([line('General William de Montfort',state.test?'Stay alive. Learn before committing. Report when you can.':'Walter will see to your supplies. Then Geoffrey will assess you. This is supervised enlistment, not permission to be reckless.','CHR-KURG')]);break;}
  showDialogue([line('General William de Montfort','No. This is a muster, Aimon, not one of your games on the hill.','CHR-KURG'),line('Aimon','Pate and Trade are out there. I should be with them.','CHR-AIMON'),line('General William de Montfort','And what will you do when the column is attacked? You have never had to hold a line, or decide whether the next blow will kill your partner.','CHR-KURG'),line('Aimon','I can learn. They had to start somewhere.','CHR-AIMON'),{...line('General William de Montfort','Then start by listening. Wanting to catch them does not make you ready for this road.','CHR-KURG'),choices:[{text:'I’m following them.',action:()=>kurgReply()},{text:'Why won’t you let me enlist?',action:()=>kurgReply()}]}]);break;
 case 'aeric':if((!state.starter&&!state.starterChosen)){showDialogue([line('Chaplain Walter Giffard','Speak with William first, Aimon. Let us make certain you are ready before the road takes you.','CHR-AERIC')]);break;}
  if(!state.blessing){showDialogue([line('Chaplain Walter Giffard','You are young for this road. I wish that were reason enough to keep you from it.','CHR-AERIC'),line('Chaplain Walter Giffard','Take these supplies. Look after your partner, and remember that the people beyond our banners are people too.','CHR-AERIC'),line('Chaplain Walter Giffard','May the Light guide you. And may you learn to look closely at what it illuminates.','CHR-AERIC')],()=>{state.blessing=true;state.poultices+=3;state.bread+=3;toast('Received 3 Poultices and 3 Trail Bread');});}else aericMenu();break;
 case 'beric':if((!state.starter&&!state.starterChosen)||!state.blessing){showDialogue([line('Instructor Geoffrey de Warenne','William must approve your enlistment, and Walter must equip you. Come back when both are done.','TRN-C01-001')]);break;}
  showDialogue([...(state.assessment?[]:[line('Dame Matilda de Clare','He is a liability, William. Unprepared soldiers get other people killed.'),line('General William de Montfort','Then we assess him before he leaves.','CHR-KURG')]),line('General William de Montfort','In real combat, there is no magical fainting. An Abyssal pushed to zero HP dies. This test has a referee and surrender rules.','CHR-KURG'),{...line('Instructor Geoffrey de Warenne',state.test?'Another supervised practice? We will stop the bout before a partner is lost.':'I have two partners. Choose your moves carefully. You may concede, and try again.','TRN-C01-001'),choices:[{text:state.test?'Practise again':'Begin the test',action:()=>{state.assessment=true;startBattle();}},{text:'Not yet',action:()=>{}}]}]);break;
 case 'shop':shop();break;
 case 'memorial':memorialMenu();break;
 case 'shrine':showDialogue([line('True Light shrine','Ivory cloth stirs above the worn stone. The village gathers under the same banners you carried in childhood.'),line('Aimon','When we played crusaders, someone always had to be the enemy.','CHR-AIMON')],()=>state.shrine=true);break;
 case 'hill':showDialogue([line('Childhood Hill','The place where the three of you played feels smaller now.'),line('Aimon','Pate dropped his wooden sword when I fell. Trade checked my hands. For a moment, nobody was an enemy.','CHR-AIMON'),line('Aimon','He promised I would come with them when I was older.','CHR-AIMON')],()=>state.hill=true);break;
 case 'exit':if(!state.test){showDialogue([line('Civeton March','The marching road lies beyond the village. Complete William’s supervised enlistment before setting out.')]);}else departure();break;
 }}
function kurgReply(){showDialogue([line('Aimon','So I’m supposed to sit here until someone decides I’m old enough?','CHR-AIMON'),line('General William de Montfort','Wild Abyssals will tear you to shreds, and that’s before the Dawnbloom get to you. I’ve heard they drink the blood of babies.','CHR-KURG'),line('Aimon','Is that your decision, or theirs?','CHR-AIMON'),line('General William de Montfort','They asked me not to enlist you. Pate and Trade. They were trying to keep you alive.','CHR-KURG'),line('Aimon','Because they still think I’m too weak.','CHR-AIMON'),line('General William de Montfort','Because they know the difference between playing at a crusade and coming home from one. You should be grateful they care.','CHR-KURG'),line('Aimon','I’m following them. With or without your permission.','CHR-AIMON'),line('General William de Montfort','…Yes. I believe you would. And leaving you to stumble after the column alone would be worse.','CHR-KURG'),line('General William de Montfort','Supervised enlistment. You choose a partner, accept Walter’s supplies, and pass Geoffrey’s assessment. Refuse any part of that, and you stay here.','CHR-KURG'),line('Aimon','Then let me prove I can listen.','CHR-AIMON')],()=>{state.kurg=true;chooseStarter();});}
let modalReturnFocus=null,modalOnClose=null;
const modalViews=createModalViewMemory();
function openModal(title,content,onClose=null){modalOnClose=onClose;if(presentationLocked)return;modalViews.remember($('.modal'),document.activeElement);if(!modal)modalReturnFocus=document.activeElement;stopMovement();modal=true;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${title}"><div class="modal-header"><h2>${title}</h2><button id="close-modal" aria-label="Close">×</button></div>${content}</section></div>`;$('#close-modal').onclick=closeModal;$('#close-modal').focus({preventScroll:true});const host=$('.modal');queueMicrotask(()=>{if(host!==$('.modal'))return;enhancePartnerLists();modalViews.restore(host);});}
function closeModal(){if(presentationLocked||state.rewardQueue?.length||state.pendingFate)return;modalViews.remember($('.modal'),document.activeElement);modal=false;$('#modal-root').innerHTML='';held=null;const afterClose=modalOnClose;modalOnClose=null;afterClose?.();if(modalReturnFocus?.isConnected)modalReturnFocus.focus();}
function chooseStarter(){
 const desc={'001':'Quick and elusive. Dark attacks reward decisive play.','004':'A thoughtful partner. Build special attack, then strike.','007':'A sturdy fighter. Powerful blows, with limited PP.'};
 openModal('Choose your first partner',`<p>Scarimp, Calibrit or Ruffurn. The other two will accompany Pate and Trade. Your original partner has three lives.</p><div class="starters">${['001','004','007'].map(id=>`<button class="starter selection-idle" data-starter="${id}"><img src="assets/${id}.webp?v=0.87.0" alt="${byId(id).name}"><h3>${byId(id).name}</h3><span>${byId(id).types[0]}</span><p>${desc[id]}</p></button>`).join('')}</div>`);
 document.querySelectorAll('[data-starter]').forEach(btn=>btn.onclick=()=>confirmStarter(btn.dataset.starter));
}
function confirmStarter(id){if(state.starterChosen)return;const s=byId(id);openModal(s.name,`<p>You’ll set out with ${s.name}. Pate and Trade will take the remaining partners.</p><div class="partner-mini"><img src="assets/${id}.webp?v=0.87.0" alt="${s.name}"><div><b>${s.name}</b><small>${s.types.join(' / ')} · Three original lives</small></div></div><div class="modal-actions"><button id="back-starters">Back</button><button class="primary" id="confirm-starter">Choose ${s.name}</button></div>`);$('#back-starters').onclick=chooseStarter;$('#confirm-starter').onclick=async()=>{if(presentationLocked)return;presentationLocked=true;document.querySelectorAll('#modal-root button').forEach(b=>b.disabled=true);$('.modal').classList.add('partner-confirmed');$('.partner-mini').classList.add('bond-animation');$('.partner-mini').insertAdjacentHTML('afterend',`<p class="bond-caption">${s.name} joins your expedition.</p>`);await delay(reducedMotion()?100:850);const moves=startingMoveIds(DATA,s,8).map(moveId);state.starter=instance(s,8,moves);state.starter.uid='unit-'+state.nextUnitId++;initializeProgress(state.starter);state.starter.originalStarter=true;state.starterChosen=true;state.starter.lives=3;starterCare(state.starter);state.party=[state.starter];state.leadUid=state.starter.uid;persist();presentationLocked=false;closeModal();refresh();nicknamePrompt(state.starter,()=>showDialogue([line('Aimon',`All right, ${unitName(state.starter)}. We’re going to catch up with them.`,'CHR-AIMON'),line('General William de Montfort','Walter first. Geoffrey second. Don’t make me repeat myself.','CHR-KURG')]));};}
function lifeEmberBagHTML(){return `<section class="field-supply"><div class="bag-item-heading"><h3>Life Ember</h3><b>× ${state.lifeEmbers||0}</b></div><p>${LIFE_EMBER.text}</p><button id="bag-use-life-ember" ${battle||state.wiped||!state.lifeEmbers?'disabled':''}>Give one extra life</button></section>`;}
function lifeEmberTarget(){
 if(battle||presentationLocked||state.wiped||!state.lifeEmbers)return;
 const living=[...state.party,...state.reserve].filter(u=>u.hp>0&&!u.dead);
 openModal('Give a Life Ember',`<p>Choose a living partner. One Ember adds one life; current HP and PP stay unchanged.</p><div class="summary-list">${living.map(u=>`<button data-life-target="${u.uid}"><b>${escapeHTML(unitName(u))}</b><small>${livesRemaining(u)} → ${livesRemaining(u)+1} lives · ${state.party.includes(u)?'Party':'Reserve'}</small></button>`).join('')}</div>`);
 document.querySelectorAll('[data-life-target]').forEach(b=>b.onclick=()=>confirmLifeEmber(b.dataset.lifeTarget));menuBack(()=>bagMenu(),'Back to bag');
}
function confirmLifeEmber(uid){
 const u=[...state.party,...state.reserve].find(u=>u.uid===uid&&u.hp>0&&!u.dead);if(!u||battle||presentationLocked||!state.lifeEmbers)return;
 openModal('One more chance',`<div class="partner-mini"><img src="${combatArtSrc(u)}" alt=""><div><b>${escapeHTML(unitName(u))}</b><small>${livesRemaining(u)} → ${livesRemaining(u)+1} lives</small></div></div><p>Use one Life Ember on this partner?</p><button id="life-ember-confirm" class="primary">Use Life Ember</button>`);
 let submitted=false;$('#life-ember-confirm').onclick=()=>{if(submitted||battle||presentationLocked||!state.lifeEmbers)return;submitted=true;let applied=false;if(!rewardTransaction(()=>{applied=grantExtraLife(state,uid);})){lifeEmberTarget();return;}if(applied){refresh();bagMenu();toast(unitName(u)+' gained one extra life');}};menuBack(lifeEmberTarget,'Cancel');
}
function memorialMenu(tab='abyssals'){
 if(room!=='town'||battle||dialogue||presentationLocked||state.wiped)return;
 const m=visitMemorialTown(state,room);
 if(m.status==='ESTABLISHED'&&m.tutorial!=='SEEN'){
  openModal('The Abyssal memorial',`<p>The stones now bear the names of your lost partners. Each entry preserves the individual you knew: its name, species, death level and place, epitaph, and final moves.</p><p>To restore one, you must sacrifice <b>10 living Abyssals of 10 different Dex species IDs for its first revival. The same individual costs 12 for its second revival, 14 for its third, then two more each time</b>. Sacrifices are permanently erased and never enter the memorial. Held items return to your bag.</p><p>The restored partner returns with its own stats and moves, full HP and PP, no status conditions, and <b>one life</b>. A full party sends it to Walter’s reserve. Human remembrance is separate.</p><button id="memorial-understood" class="primary">Read the memorial</button>`);
  $('#memorial-understood').onclick=()=>{if(!rewardTransaction(()=>{memorialState(state).tutorial='SEEN';state.memorial=true;}))return;memorialMenu(tab);};return;
 }
 openModal('Civeton memorial',`<div class="bag-pockets" role="tablist"><button id="memorial-abyssals" role="tab" aria-selected="${tab==='abyssals'}">Lost Abyssals · ${state.dead.length}</button><button id="memorial-human" role="tab" aria-selected="${tab==='human'}">Human remembrance</button></div>${tab==='human'?[...HUMAN_MEMORIAL,...companionHumanMemorial(state)].map(h=>`<article><h3>${h.name}</h3><p>${h.epitaph}</p></article>`).join('')+'<p>These stones are for remembrance. Human resurrection is unavailable.</p>':m.status!=='ESTABLISHED'?'<p>No Abyssal names have been carved here yet. After your first permanent loss, return to Civeton to establish their memorial.</p>':`<p>Names appear in the order your partners were lost.</p><div class="summary-list">${state.dead.map(u=>`<button data-memorial-unit="${u.uid}"><img class="memorial-sprite" src="${combatArtSrc(u)}" alt=""><b>${escapeHTML(unitName(u))}</b><small>${escapeHTML(u.species.name)} · Lv. ${u.deathLevel} · ${escapeHTML(u.deathLocation)}</small></button>`).join('')||'<p>No partners remain in the memorial. Their stones stand ready, should the road take another.</p>'}</div><p>${m.totalPermanentDeaths} permanent losses · ${m.totalResurrections} resurrections · ${m.totalSacrifices} sacrifices</p>`}`);
 $('#memorial-abyssals').onclick=()=>memorialMenu();$('#memorial-human').onclick=()=>memorialMenu('human');document.querySelectorAll('[data-memorial-unit]').forEach(b=>b.onclick=()=>memorialEntry(b.dataset.memorialUnit));
}
function memorialEntry(uid){
 if(room!=='town'||battle||presentationLocked||state.wiped)return;const u=state.dead.find(u=>u.uid===uid);if(!u){memorialMenu();return;}const q=resurrectionQuote(state,uid,[]);
 openModal('Remember '+escapeHTML(unitName(u)),`<div class="partner-mini"><img src="${combatArtSrc(u)}" alt=""><div><b>${escapeHTML(unitName(u))}</b><small>${escapeHTML(u.species.name)} · Lost at Lv. ${u.deathLevel}<br>${escapeHTML(u.deathLocation)}</small></div></div><blockquote>${escapeHTML(u.deathEpitaph)}</blockquote><h3>Final moves</h3><div class="summary-moves">${u.moves.slice(0,4).map(m=>`<article>${compactMoveHTML(m)}</article>`).join('')}</div><p>This partner has been resurrected ${q.revivals} time(s). Its next resurrection requires ${q.cost} living partners of ${q.cost} different species. Your restored partner has one life.</p><button id="memorial-resurrect">Choose ${q.cost} sacrifices</button>`);
 $('#memorial-resurrect').onclick=()=>memorialSacrifices(uid,[]);menuBack(()=>memorialMenu(),'Back to the memorial');
}
function memorialSacrifices(uid,selected){
 if(room!=='town'||battle||presentationLocked||state.wiped||!state.dead.some(u=>u.uid===uid))return;
 const living=[...state.party,...state.reserve].filter(u=>u.hp>0&&!u.dead),chosen=selected.map(id=>living.find(u=>u.uid===id)).filter(Boolean),species=new Set(chosen.map(u=>u.species.id)),q=resurrectionQuote(state,uid,selected);
 openModal('Choose the sacrifices',`<p><b>${chosen.length} / ${q.cost} partners selected · ${species.size} distinct species</b></p><p>Each selection must have a different Dex species ID. These partners will be permanently erased. They cannot be resurrected afterwards. You will review every name before confirming.</p><div class="summary-list">${living.map(u=>{const picked=selected.includes(u.uid);return `<button data-sacrifice="${u.uid}" aria-pressed="${picked}" ${!picked&&(selected.length>=q.cost||species.has(u.species.id))?'disabled':''}><b>${picked?'✓ ':''}${escapeHTML(unitName(u))}</b><small>${escapeHTML(u.species.name)} · Dex ${u.species.id} · Lv. ${u.level} · ${state.party.includes(u)?'Party':'Reserve'}${u.originalStarter?' · ORIGINAL STARTER':u.favourite||u.favorite?' · FAVOURITE':u.nickname?' · Named partner':''}</small></button>`;}).join('')}</div><p>${q.ok?'Ready to review.':q.reason}</p><button id="sacrifice-review" class="primary" ${q.ok?'':'disabled'}>Review ${q.cost} sacrifices</button>`);
 document.querySelectorAll('[data-sacrifice]').forEach(b=>b.onclick=()=>{const id=b.dataset.sacrifice,u=living.find(u=>u.uid===id),picked=selected.includes(id);if(!picked&&(selected.length>=q.cost||species.has(u.species.id)))return;memorialSacrifices(uid,picked?selected.filter(x=>x!==id):[...selected,id]);});$('#sacrifice-review').onclick=()=>confirmResurrection(uid,selected);menuBack(()=>memorialEntry(uid),'Cancel');
}
function confirmResurrection(uid,selected){
 if(room!=='town'||battle||presentationLocked||state.wiped)return;const q=resurrectionQuote(state,uid,selected);if(!q.ok){memorialSacrifices(uid,selected);return;}
 const special=q.donors.filter(u=>u.originalStarter||u.favourite||u.favorite||u.nickname);
 openModal('Confirm permanent sacrifices',`<p>Restore <b>${escapeHTML(unitName(q.target))}</b> by permanently sacrificing these ${q.cost} partners:</p><ol>${q.donors.map(u=>`<li><b>${escapeHTML(unitName(u))}</b> · ${escapeHTML(u.species.name)} · Lv. ${u.level}</li>`).join('')}</ol>${special.length?`<p class="danger"><b>Warning: your selection includes an original starter, favourite or named partner:</b> ${special.map(u=>escapeHTML(unitName(u))+(u.originalStarter?' (original starter)':'')).join(', ')}. Their extra lives do not protect them from sacrifice.</p>`:''}<p>All ${q.cost} disappear permanently and are excluded from the memorial. Their held items return to your bag. This cannot be undone in this expedition.</p><label><input type="checkbox" id="sacrifice-ack"> I understand that all ${q.cost} selected partners will be permanently erased.</label><button id="sacrifice-confirm" class="primary" disabled>Sacrifice ${q.cost} · Restore ${escapeHTML(unitName(q.target))}</button>`);
 $('#sacrifice-ack').onchange=()=>$('#sacrifice-confirm').disabled=!$('#sacrifice-ack').checked;
 $('#sacrifice-confirm').onclick=()=>{if(!$('#sacrifice-ack').checked||battle||presentationLocked||room!=='town'||!resurrectionQuote(state,uid,selected).ok)return;let restored=null;if(!rewardTransaction(()=>{restored=resurrectPartner(state,uid,selected);})){confirmResurrection(uid,selected);return;}if(restored){buildMarkers();memorialMenu();toast(unitName(restored)+' restored · one life · '+(state.party.includes(restored)?'Party':'Walter’s reserve'));}};menuBack(()=>memorialSacrifices(uid,selected),'Cancel');
}

function relearnMenu(){
 if(battle||presentationLocked||state.wiped||!PRIEST_RETURNS[room])return;
 const units=[...state.party,...state.reserve].filter(u=>u.hp>0&&!u.dead);
 openModal('Walter · Free move relearning',`<p>Choose a partner from your party or reserve. Relearning is free. You can recover eligible moves from its current form and its recorded earlier forms.</p><div class="summary-list">${units.map(u=>`<button data-relearn-unit="${u.uid}"><b>${escapeHTML(unitName(u))}</b><small>Lv. ${u.level} · ${relearnPool(u).length} available moves</small></button>`).join('')||'<p>No living partners are available.</p>'}</div>`);
 document.querySelectorAll('[data-relearn-unit]').forEach(b=>b.onclick=()=>relearnUnitMenu(b.dataset.relearnUnit));menuBack(aericMenu,'Back to Walter');
}
function relearnUnitMenu(uid){
 if(battle||presentationLocked||!PRIEST_RETURNS[room])return;
 const u=[...state.party,...state.reserve].find(u=>u.uid===uid&&u.hp>0&&!u.dead);if(!u){relearnMenu();return;}
 const moves=relearnPool(u);
 openModal('Relearn · '+escapeHTML(unitName(u)),`<p>Free relearning · choose a move. With four moves, choose and confirm which one to replace.</p><div class="move-learning-list">${moves.map(m=>`<button class="typed-move" style="--move-type:${TYPE_COLORS[m.type_id]}" data-relearn-move="${m.id}">${compactMoveHTML(m)}</button>`).join('')||'<p>All eligible moves are already equipped. More become available as this partner levels up.</p>'}</div>`);
 document.querySelectorAll('[data-relearn-move]').forEach(b=>b.onclick=()=>{const m=moves.find(m=>m.id===+b.dataset.relearnMove);if(!m)return;moveLearning(u,m,{cancel:()=>relearnUnitMenu(uid),finish:slot=>{
  if(slot===null){relearnUnitMenu(uid);return;}
  const current=[...state.party,...state.reserve].find(u=>u.uid===uid);
  if(!current||!relearnPool(current).some(move=>move.id===m.id)){relearnUnitMenu(uid);return;}
  let applied=false;const saved=rewardTransaction(()=>{applied=applyRelearn(current,m.id,slot);});
  relearnUnitMenu(uid);if(saved&&applied){refresh();toast(unitName(current)+' relearned '+m.name+' · free');}
 }});});menuBack(relearnMenu,'Choose another partner');
}
function salvationTutor(){if(battle||presentationLocked||!PRIEST_RETURNS[room])return;const units=[...state.party,...state.reserve].filter(u=>u.hp>0&&!u.dead&&!u.moves.some(m=>m.id===SALVATION_ID));openModal('Walter · First Light Salvation',`<p>Every Abyssal can learn this free restraint technique. It uses its stronger attacking stat and leaves the target with at least 1 HP. Choose a partner, then a move slot.</p><div class="summary-list">${units.map(u=>`<button data-salvation-unit="${u.uid}"><b>${escapeHTML(unitName(u))}</b><small>${resolveSalvationMove(u,SALVATION_MOVE).category==='SPECIAL'?'Special':'Physical'} · Power 60 · 20 PP</small></button>`).join('')||'<p>Every available partner already knows Salvation.</p>'}</div>`);document.querySelectorAll('[data-salvation-unit]').forEach(button=>button.onclick=()=>{const u=[...state.party,...state.reserve].find(u=>u.uid===button.dataset.salvationUnit);if(!u)return;moveLearning(u,resolveSalvationMove(u,SALVATION_MOVE),{cancel:salvationTutor,finish:slot=>{if(slot===null){salvationTutor();return;}let taught=false;if(rewardTransaction(()=>{const current=[...state.party,...state.reserve].find(p=>p.uid===u.uid);taught=teachSalvation(current,slot);} )&&taught)toast(unitName(u)+' learned First Light Salvation · free');salvationTutor();}});});menuBack(aericMenu,'Back to Walter');}
function atTravelHub(){const hub=TRAVEL_HUBS.find(h=>h.room===room);return hub&&Math.abs(player.x-hub.x)+Math.abs(player.y-hub.y)<=1;}
function fastTravelMenu(){
 if(battle||dialogue||presentationLocked||state.wiped||!atTravelHub())return;
 if(!fastTravelUnlocked(state)){openModal('Caravan hub', '<p>Defeat the first city leader to open paid caravan routes between places you have already visited. Every major town has a hub.</p>');return;}
 openModal('Caravan · '+roomName(room),`<p>Choose a place you have already visited. New destinations join the caravan list when you reach them. Town fares are 100 doubloons; the Sunken Fort fare is 150. Transport preserves your partners’ health and move PP.</p><p><b>${state.money} doubloons available</b></p><div class="summary-list">${travelDestinations(state,room).map(h=>{const q=travelQuote(state,room,h.room);return `<button data-travel-to="${h.room}" ${q.ok?'':'disabled'}><b>${h.name}</b><small>${q.cost} doubloons${q.ok?'':' · '+q.reason}</small></button>`;}).join('')}</div>`);
 document.querySelectorAll('[data-travel-to]').forEach(b=>b.onclick=()=>confirmFastTravel(b.dataset.travelTo));
}
function confirmFastTravel(to){
 const q=travelQuote(state,room,to);if(!q.ok||!atTravelHub()||battle||presentationLocked)return;
 openModal('Travel to '+q.destination.name,`<p>Pay <b>${q.cost} doubloons</b> to travel to ${q.destination.name}? You will have ${state.money-q.cost} doubloons left.</p><button id="travel-confirm" class="primary">Pay and travel</button>`);
 $('#travel-confirm').onclick=()=>void useFastTravel(to);menuBack(fastTravelMenu,'Cancel');
}
function commitFastTravel(to){
 const q=travelQuote(state,room,to);if(!q.ok||!atTravelHub())return false;
 const backup=JSON.parse(JSON.stringify(state)),previousRoom=room,previousDoor=returnDoor,position={x:player.x,y:player.y,facing:player.facing};
 if(!payTravelFare(state,room,to))return false;
 room=to;returnDoor=null;if(room==='philomere')hospiceQuest(state).cityVisited=true;enterTrainerArea(state,room);
 setPlayer(...nearestWalkable(room,...q.destination.arrival.slice(0,2)),q.destination.arrival[2]);$('#location').textContent=roomName(room);buildMarkers();
 if(!persist()){Object.assign(state,backup);state.party=state.party.map(hydrate);state.reserve=state.reserve.map(hydrate);state.dead=state.dead.map(hydrate);state.starter=state.party.concat(state.reserve,state.dead).find(u=>u.originalStarter)||null;room=previousRoom;returnDoor=previousDoor;setPlayer(position.x,position.y,position.facing);$('#location').textContent=roomName(room);buildMarkers();return false;}
 encounterGrace=3;trainerGrace=performance.now()+2000;const route=areaRoute();preloadCombatArt(route.tables.flatMap(t=>t.slots.map(s=>s.species_id)));return true;
}
async function useFastTravel(to){
 if(battle||dialogue||presentationLocked||!state.begun||state.wiped||state.rewardQueue?.length||state.pendingFate||state.rewardHandoff||!atTravelHub()||!travelQuote(state,room,to).ok)return false;
 closeModal();stopMovement();presentationLocked=true;$('#world-warp').hidden=false;
 try{await delay(reducedMotion()?80:200);const success=commitFastTravel(to);await delay(reducedMotion()?80:200);if(success)toast('Caravan arrived · '+roomName(room));return success;}
 finally{$('#world-warp').hidden=true;presentationLocked=false;}
}

function aericMenu(){openModal('Chaplain Walter Giffard',`<p>Reserve care and move relearning are available through Walter in towns.</p><p>Your expedition contains ${state.party.filter(u=>u.hp>0).length} living partners; ${state.reserve.length} wait in reserve.</p><div class="modal-actions"><button id="aeric-reserve">Party and reserve</button><button id="relearn">Review known moves</button><button id="walter-salvation">Learn First Light Salvation</button><button id="walter-secret">Quest move tutors</button><button id="walter-abilities">Ability attunement</button><button id="walter-stewardship">Stewardship & rehoming</button><button id="walter-nursery">Nursery & eggs</button><button id="walter-rematches">Spared leader rematches</button><button id="aeric-rest" class="primary">Rest your partner</button></div>`);$('#aeric-reserve').onclick=()=>partyMenu(true);$('#aeric-rest').onclick=restAtPriest;$('#relearn').onclick=relearnMenu;$('#walter-salvation').onclick=salvationTutor;$('#walter-secret').onclick=questTutorMenu;$('#walter-abilities').onclick=attunementMenu;$('#walter-stewardship').onclick=stewardshipMenu;$('#walter-nursery').onclick=nurseryMenu;$('#walter-rematches').onclick=leaderRematchMenu;}
function shop(stockRoom=room){if(battle)return;if(typeof stockRoom!=='string')stockRoom=room;const keeper={...(SHOPKEEPERS[stockRoom]||SHOPKEEPERS.shop),stockRoom};openModal(keeper.name,`<div class="shopkeeper-hero"><img src="assets/${keeper.id}.webp" alt="${keeper.name}"><p>“${keeper.greeting}”<br>You have <b>${state.money.toLocaleString('en-GB')} doubloons</b>.</p></div><button id="shop-relic-forge">Relic armour · Rivet and six evolution cores</button>${shopStock(stockRoom,state).map(item=>`<div class="shop-row"><div>${item.icon?`<img class="capture-food-icon" src="${item.icon}" alt="">`:""}<b>${item.name}</b><p>${item.text} Owned: ${state[item.key]||0}</p></div><button id="buy-${item.id}" ${state.money<item.price?'disabled':''}>Buy · ${item.price}</button></div>`).join('')}`);$('#shop-relic-forge').onclick=relicForgeMenu;for(const item of shopStock(stockRoom,state))$('#buy-'+item.id).onclick=()=>shopQuantity(item,keeper);}
function shopQuantity(item,keeper){const max=purchaseQuote(state,item,1).max;openModal('Buy '+item.name,`<div class="shopkeeper-hero"><img src="assets/${keeper.id}.webp" alt="${keeper.name}"><p>${item.price} doubloons each · You own ${state[item.key]||0}.</p></div><label for="shop-quantity">How many?</label><div class="quantity-picker"><button id="quantity-minus" aria-label="Buy one fewer">−</button><input id="shop-quantity" type="number" inputmode="numeric" min="1" max="${max}" step="1" value="1"><button id="quantity-plus" aria-label="Buy one more">+</button><button id="quantity-max">Max</button></div><p id="purchase-total" role="status"></p><div class="modal-actions"><button id="purchase-back">Back</button><button id="purchase-confirm" class="primary">Buy</button></div>`);const input=$('#shop-quantity');const update=()=>{const q=purchaseQuote(state,item,input.value);$('#purchase-total').textContent=q.valid?'Total · '+q.total.toLocaleString('en-GB')+' doubloons · '+(state.money-q.total).toLocaleString('en-GB')+' remaining':'Enter a whole number from 1 to '+q.max+'.';$('#purchase-confirm').disabled=!q.valid;$('#quantity-minus').disabled=Number(input.value)<=1;$('#quantity-plus').disabled=Number(input.value)>=q.max;};input.oninput=update;$('#quantity-minus').onclick=()=>{input.value=Math.max(1,(Number(input.value)||1)-1);update();};$('#quantity-plus').onclick=()=>{input.value=Math.min(max,(Number(input.value)||0)+1);update();};$('#quantity-max').onclick=()=>{input.value=max;update();};$('#purchase-back').onclick=()=>shop(keeper.stockRoom);$('#purchase-confirm').onclick=()=>{const q=purchaseQuote(state,item,input.value);if(!q.valid)return;if(rewardTransaction(()=>buySupplies(state,item,q.quantity))){refresh();shop(keeper.stockRoom);blip();}};update();}
function supplies(){if(battle||dialogue||!state.begun)return;bagMenu();}
function departure(){if(state.departed){void warp('march',3,17,'right');return;}if(!state.deathExplained){explainLives();return;}showDialogue([line('General William de Montfort','Stay alive. Learn before committing. Report when you can.','CHR-KURG'),line('Aimon','Pate. Trade. I’m coming.','CHR-AIMON'),line('Civeton March','The village falls behind you. The road to Dorelem lies ahead.')],()=>{state.departed=true;state.routeReached=true;refresh();void warp('march',3,17,'right');});}
function startBattle(){if(battle||presentationLocked)return;closeModal();stopMovement();const original=lead();if(!original){toast('No living expedition partner.');return;}const p=instance(original.species,original.level,original.moves);p.uid=original.uid;p.stats={...original.stats};p.maxHp=original.maxHp;p.hp=p.maxHp;p.nickname=original.nickname;p.originalStarter=original.originalStarter;p.lives=original.lives;p.lifeCapacity=original.lifeCapacity;p.lifeEmbersReceived=original.lifeEmbersReceived;const enemies=DATA.trainer.team.map(t=>{const u=instance(byId(t.species_id),t.level,t.current_form_legal_move_ids.map(moveId).filter(m=>m.category!==null));u.uid='beric-'+t.species_id;return assignShiny(initializeProgress(u));});
 battle={kind:'practice',participants:[p.uid],defeats:[],player:p,enemies,index:0,round:1,random:rng(9317+Number(p.species.id)),busy:false,log:'A supervised test. Use moves, manage PP, and stop before anyone is lost.',history:[],finished:false,phase:'trainer',sendOut:false};initializeBattleAbilities(battle);battle.busy=true;$('#battle').hidden=false;$('#viewport').classList.add('battling');$('#touch-controls').hidden=false;$('#markers').hidden=true;$('#interact').disabled=true;$('#context').textContent='Select a move · Supervised combat stops before lethal damage.';renderBattle();void firstSendOut();}
const hpHud=(unit,playerSide)=>`<div class="combat-hud" data-health-key="${healthKey(unit)}"><div class="hud-row"><b title="${escapeHTML(unitName(unit))}">${escapeHTML(unitName(unit))}</b><small>Lv. ${unit.level}</small></div><small class="hud-types">${unit.nickname?unit.species.name+' · ':''}${unit.species.types.join(' / ')}</small><div class="hp-track"><i class="${shownHP(unit)/unit.maxHp<.3?'low':''}" style="width:${shownHP(unit)/unit.maxHp*100}%"></i></div><div class="hp-numbers">${shownHP(unit)} / ${unit.maxHp} HP</div>${playerSide?unit.originalStarter||unit.lifeEmbersReceived?`<div class="lives" aria-label="${livesRemaining(unit)} lives remaining">${'◆ '.repeat(livesRemaining(unit))}${'◇ '.repeat(lifeCapacity(unit)-livesRemaining(unit))}<small>Lives remaining</small></div>`:'<div class="life-label">Ordinary partner · one life</div>':''}<div class="battle-ability">${escapeHTML(abilityName(unit)||'')}</div><details class="condition-details"><summary>${unit.status||unit.confusion?'Conditions · '+(unit.status||'CONFUSION').replaceAll('_',' '):'Battle effects'}</summary>${statusHTML(unit)||'<small>No conditions or temporary effects.</small>'}</details><div class="stage-note">${Object.entries(unit.stages).filter(([,v])=>v).map(([s,v])=>`${s.replaceAll('_',' ')} ${v>0?'+':''}${v}`).join(' · ')||''}</div></div>`;
function paintTypeFeedback(){if(!battle)return;let node=$('#type-feedback');if(!node){node=document.createElement('div');node.id='type-feedback';node.setAttribute('role','status');$('#battle').append(node);}const feedback=battle.typeFeedback;node.hidden=!feedback||feedback.value===1;if(!feedback)return;node.className='type-feedback '+effectivenessClass(feedback.value);node.textContent=(feedback.who==='enemy'?'Enemy’s ':'Your ')+feedback.type+' · '+effectivenessLabel(feedback.value);}
function typeChartMenu(){if(battle?.busy||battle?.finished)return;hideMoveDetails();const enemy=battle?.enemies[battle.index??0],attack=battle?.player.moves[battle.selectedMove??0]?.type_id||lead()?.species.types[0]||'NORMAL',defenders=enemy?.species.types||lead()?.species.types||['NORMAL'];openModal('Type chart',typeChartHTML(attack,defenders));const update=()=>{$('#chart-matchup').innerHTML=matchupHTML($('#chart-attack').value,[$('#chart-defender').value,$('#chart-second').value].filter(Boolean));};for(const id of ['chart-attack','chart-defender','chart-second'])$('#'+id).onchange=update;}
function specialistBattleHTML(b,target=b.enemies[0]){const locked=b.busy||b.finished||b.player.hp<=0;return SPECIALIST_FOODS.filter(i=>!b.finaleDouble&&state[i.key]>0).map(i=>`<button data-special-food="${i.key}" ${locked||(!b.relicDouble&&(b.trainer||b.questGuard))||!target||target.hp<=0?'disabled':''}><img class="capture-food-icon" src="${i.icon}" alt="">${i.name} × ${state[i.key]}<small>${target?formatCaptureChance(target,specialistStrength(i.key,target,b.round)):'0%'} chance · ${specialistStrength(i.key,target,b.round)}× food strength</small></button>`).join('')+SPECIALIST_MEDICINES.filter(i=>state[i.key]>0).map(i=>{const p=medicinePreview(b.player,i.key);return `<button data-battle-medicine="${i.key}" ${locked||!p.usable?'disabled':''}><img class="capture-food-icon" src="${i.icon}" alt="">${i.name} × ${state[i.key]}<small>Restore ${p.hp} HP${p.cure?' · cure status':''}</small></button>`;}).join('');}
function bindSpecialistBattle(){document.querySelectorAll('[data-special-food]').forEach(el=>el.onclick=()=>wildTurn({food:el.dataset.specialFood}));document.querySelectorAll('[data-battle-medicine]').forEach(el=>el.onclick=()=>wildTurn({medicine:el.dataset.battleMedicine}));}
function specialistMedicineTarget(key){const item=SPECIALIST_MEDICINES.find(i=>i.key===key);if(!item)return;openModal(item.name,`<p>${item.text} Owned: ${state[key]||0}.</p><div class="summary-list">${state.party.map(u=>{const p=medicinePreview(u,key);return `<button class="summary-choice" data-special-target="${u.uid}" ${!state[key]||!p.usable?'disabled':''}><img src="${combatArtSrc(u)}" alt=""><span><b>${escapeHTML(unitName(u))}</b><small>${u.hp} / ${u.maxHp} HP · Restore ${p.hp}${p.cure?' · cure status':''}</small></span></button>`;}).join('')}</div>`);document.querySelectorAll('[data-special-target]').forEach(el=>el.onclick=()=>{const u=state.party.find(u=>u.uid===el.dataset.specialTarget);if(!u||!medicinePreview(u,key).usable||!state[key])return;let result;if(rewardTransaction(()=>result=useSpecialistMedicine(state,u,key))&&result){refresh();bagMenu();toast(item.name+' restored '+result.hp+' HP'+(result.cured?' and cured status.':'.'));}});menuBack(()=>bagMenu(),'Back to bag');}
function battleCommands(b){
 const wild=b.kind==='wild',disabled=b.busy||b.finished,dead=b.player.hp<=0,menu=b.commandMenu;
 const back='<div class="battle-command-tools"><button data-battle-menu="" class="battle-back">Back</button><button data-type-chart class="battle-back">Type chart</button></div>';
 if(menu==='fight')return `${back}${!b.player.moves.some(m=>moveUsable(b.player,m))?'<button id="battle-wait">Wait one turn</button>':''}<div class="battle-actions">${b.player.moves.map((m,i)=>`<div class="move-slot"><button class="move typed-move" style="--move-type:${TYPE_COLORS[m.type_id]}" aria-label="${escapeHTML(m.name)} · ${categoryLabel(m.category)} · ${m.type_id} · ${m.left} of ${m.pp} PP" data-move="${i}" ${disabled||dead||!moveUsable(b.player,m)?'disabled':''}><b><span class="move-category" title="${categoryLabel(m.category)}" aria-hidden="true">${categorySymbol(m.category)}</span> ${m.name}</b><small>${m.type_id} · ${m.left}/${m.pp} PP ${movePriority(m,b.player)>0?'<span class="priority-tag">Priority +'+movePriority(m,b.player)+'</span>':''}${!moveUsable(b.player,m)&&m.left>0?' · SEALED':''} ${m.power?`<span class="matchup ${effectivenessClass(moveMatchup(m,b.enemies[b.index??0]))}">${moveMatchup(m,b.enemies[b.index??0])}×</span>`:``}</small></button><button class="inspect-move" data-inspect="${i}" aria-label="Details for ${m.name}" ${disabled?'disabled':''}>i</button></div>`).join('')}</div>`;
 if(menu==='switch')return `${back}<div class="battle-partners">${state.party.map(u=>`<button data-battle-switch="${u.uid}" ${disabled||u.hp<=0||u===b.player?'disabled':''}><b>${escapeHTML(unitName(u))}</b><small>${u.hp} / ${u.maxHp} HP${u===b.player?' · Active':''}</small></button>`).join('')}</div>`;
 if(menu==='item')return `${back}<div class="battle-actions">${wild?specialistBattleHTML(b):''}<button id="${wild?'wild-heal':'battle-heal'}" ${disabled||dead||!state.poultices||b.player.hp>=b.player.maxHp?'disabled':''}>Poultice × ${state.poultices}<small>Restore up to ${Math.min(b.player.maxHp-b.player.hp,Math.floor(Math.min(50,Math.floor(b.player.maxHp/2))*healingMultiplier(b.player)))} HP</small></button>${wild?`<button id="offer-food" ${disabled||dead||b.trainer||b.questGuard||!state.bread?'disabled':''}>Trail Bread × ${state.bread}<small>${b.questGuard?'The guardian must be defeated':b.trainer?'Wild Abyssals only':formatCaptureChance(b.enemies[0])+' chance'}</small></button>${`<button id="offer-hearty-food" ${disabled||dead||b.trainer||b.questGuard||!state.heartyFood?'disabled':''}>Hearty Ration × ${state.heartyFood||0}<small>${b.questGuard?'The guardian must be defeated':b.trainer?'Wild Abyssals only':formatCaptureChance(b.enemies[0],2)+' chance · 2× food strength'}</small></button>`}${state.freshMeat>0?`<button id="offer-fresh-meat" ${disabled||dead||b.trainer||b.questGuard?'disabled':''}><img class="capture-food-icon" src="${FRESH_MEAT.icon}" alt="">Fresh Meat × ${state.freshMeat}<small>${formatCaptureChance(b.enemies[0],FRESH_MEAT_MODIFIER)} chance · 6× food strength</small></button>`:''}${state.patientRations>0?`<button id="offer-patient-food" ${disabled||dead||b.trainer||b.questGuard?'disabled':''}>Patient Ration × ${state.patientRations}<small>${formatCaptureChance(b.enemies[0],patientStrength(b.round))} chance · ${patientStrength(b.round).toFixed(1)}× food strength</small></button>`:''}${state.winterPreserves>0?`<button id="offer-preserve" ${disabled||dead||b.trainer||b.questGuard?'disabled':''}>Winter Preserve × ${state.winterPreserves}<small>${formatCaptureChance(b.enemies[0],preserveStrength(b.enemies[0]))} chance · ${preserveStrength(b.enemies[0])}× food strength</small></button>`:''}${b.jettyId||b.fishingDay!==null&&b.fishingDay!==undefined?`<button id="offer-bait" ${disabled||dead||!canOfferRiverBait(state,b)?'disabled':''}>River Bait × ${state.riverBait||0}<small>${formatCaptureChance(b.enemies[0],waterBaitModifier(b.enemies[0]))} chance · Water-type catch</small></button>`:''}`:''}</div>`;
 if(menu==='run')return `${back}<div class="battle-actions"><button id="${wild?b.nonlethal?'wild-concede':b.trainer?'wild-smoke':'wild-run':'battle-concede'}" ${disabled||dead||wild&&b.trainer&&!b.nonlethal&&!state.smoke?'disabled':''}>${wild?b.nonlethal?'Concede practice':b.trainer?'Smoke Bomb × '+state.smoke:'Run':'Concede practice'}<small>${wild&&!b.trainer?'80% escape · escape abilities guarantee it':wild&&b.trainer&&!b.nonlethal?'Guaranteed escape from this trainer':'Leave this challenge'}</small></button></div>`;
 return `<div class="battle-actions command-menu">${[['fight','Fight',dead],['switch','Switch',!wild||!state.party.some(u=>u.hp>0&&u!==b.player)],['item','Item',dead],['run','Run',dead]].map(([id,label,blocked])=>`<button data-battle-menu="${id}" ${disabled||blocked?'disabled':''}>${label}</button>`).join('')}</div>`;
}
function bindBattleCommands(){bindSpecialistBattle();paintTypeFeedback();$('#battle-wait')?.addEventListener('click',()=>battle?.kind==='wild'?wildTurn({wait:true}):battleTurn('wait'));document.querySelectorAll('[data-type-chart]').forEach(el=>el.onclick=typeChartMenu);document.querySelectorAll('[data-battle-menu]').forEach(el=>el.onclick=()=>{if(!battle||battle.busy||battle.finished)return;battle.commandMenu=el.dataset.battleMenu||null;hideMoveDetails();if(battle.kind==='wild'&&!battle.trainer&&el.dataset.battleMenu==='run'){void wildTurn({run:true});return;}renderBattle();});document.querySelectorAll('[data-battle-switch]').forEach(el=>el.onclick=()=>wildTurn({switchUid:el.dataset.battleSwitch}));}

function renderBattle(){if(!battle)return;for(const u of [battle.player,...battle.enemies,battle.alliedRivet].filter(Boolean))for(const m of u.moves)if(m.adaptiveCategory)m.category=resolveSalvationMove(u,m).category;if(battle.relicDouble){renderRelicDouble();return;}if(battle.kind==='wild'||battle.kind==='lesson'){renderWildBattle();return;}const b=battle,e=b.enemies[b.index];$('#battle').innerHTML=`<div class="battle-top">${hpHud(e,false)}<div class="battle-meta">INSTRUCTOR BERIC<br>Supervised · Round ${b.round}<br>Partner ${b.index+1} / 2</div></div><div class="enemy-zone">${['trainer','calling'].includes(b.phase)?'':`<div class="summon-ring ${b.sendOut?'active':''}"></div>${b.artReady===false?'<span class="art-loading" role="status">An Abyssal approaches…</span>':`<img class="enemy-art ${b.sendOut?'send-out':''}" fetchpriority="high" decoding="sync" src="${combatArtSrc(e)}" alt="${e.species.name}">`}`}</div><div class="battle-bottom">${hpHud(b.player,true)}<div class="battle-panel"><div class="command-heading">${escapeHTML(state.playerName.toUpperCase())}’S COMMANDS</div><div class="battle-log" role="status" aria-live="polite">${escapeHTML(b.log)}</div>${battleCommands(b)}</div></div><div id="move-inspector" class="move-inspector" role="tooltip" hidden></div>${b.phase==='trainer'?`<div class="trainer-intro"><div class="trainer-intro-art"><img src="assets/TRN-C01-001.webp" alt="Instructor Geoffrey de Warenne, full-body introduction"></div><div class="trainer-intro-caption"><span class="eyebrow">SUPERVISED ENLISTMENT</span><h2>Instructor Geoffrey de Warenne</h2><p>“Stand steady, Pennkit.”</p><span>Preparing his first Abyssal…</span></div></div>`:''}`;
 document.querySelectorAll('[data-move]').forEach(el=>{el.onclick=()=>battleTurn(+el.dataset.move);el.onmouseenter=el.onfocus=()=>inspectMove(+el.dataset.move);el.onmouseleave=()=>{if(document.activeElement!==el)hideMoveDetails();};el.onblur=hideMoveDetails;});
 document.querySelectorAll('[data-inspect]').forEach(el=>el.onclick=()=>{hideMoveDetails();const m=b.player.moves[+el.dataset.inspect];openModal(m.name,detailsHTML(m,b.player,e));});
 $('#battle-heal')?.addEventListener('click',()=>battleTurn('heal'));$('#battle-concede')?.addEventListener('click',()=>{if(!b.busy)endBattle(false);});
 bindBattleCommands();restoreBattleSelection();
}
function restoreBattleSelection(){if(!battle||battle.busy||battle.finished||modal)return;const move=$(`#battle [data-move="${battle.selectedMove??0}"]:not(:disabled)`)||$('#battle button:not(:disabled)');move?.focus({preventScroll:true});}
function inspectMove(i){if(!battle||battle.busy||modal)return;const panel=$('#move-inspector');panel.innerHTML=detailsHTML(battle.player.moves[i],battle.player,battle.enemies[battle.index??0],{supervised:battle.kind!=='wild'});panel.hidden=false;}
function hideMoveDetails(){const panel=$('#move-inspector');if(panel)panel.hidden=true;}
function reducedMotion(){return isReducedMotion();}
async function firstSendOut(){const b=battle;await battleArtReady(b.player,...b.enemies);if(battle!==b)return;await delay(reducedMotion()?100:1500);if(battle!==b)return;b.phase='calling';b.log=`${state.playerName} calls ${unitName(b.player)}.`;renderBattle();$('#fx').innerHTML='<div class="foreground-call"></div>';await delay(reducedMotion()?100:550);$('#fx').innerHTML='';if(battle!==b)return;await enemySendOut();if(battle!==b)return;b.busy=false;renderBattle();}
async function enemySendOut(){const b=battle;if(!b)return;b.phase='sending';b.sendOut=true;b.log=`Instructor Geoffrey de Warenne sends out ${b.enemies[b.index].species.name}.`;b.history.push(b.log);renderBattle();blip(740);await delay(reducedMotion()?100:950);if(battle!==b)return;b.sendOut=false;b.phase='ready';renderBattle();}
const delay=ms=>new Promise(r=>setTimeout(r,ms));
function holdBeforeImpact(result){if(result.hpChanges?.length){presentationHealth??={};for(const h of result.hpChanges)presentationHealth[h.key]=h.before;}}
async function drainHealth(result){const changes=(result.hpChanges||[]).filter(h=>h.before!==h.after);if(!changes.length)return;presentationHealth??={};const duration=reducedMotion()?0:760;await new Promise(resolve=>{const start=performance.now();function frame(now){const t=duration?Math.min(1,(now-start)/duration):1;for(const h of changes){const value=presentedHP(h,t);presentationHealth[h.key]=value;for(const hud of document.querySelectorAll('[data-health-key]'))if(hud.dataset.healthKey===h.key){const bar=hud.querySelector('.hp-track i');bar.style.width=(value/h.maxHp*100)+'%';bar.classList.toggle('low',value/h.maxHp<.3);hud.querySelector('.hp-numbers').textContent=value+' / '+h.maxHp+' HP';}}if(t<1)requestAnimationFrame(frame);else resolve();}requestAnimationFrame(frame);});}
async function animateWrath(changes){const current=battle;if(!current)return;for(const change of changes){if(change.speciesId!=='381')continue;const u=[current.player,...current.enemies].find(u=>(u.uid||u.species.id)===change.uid);if(!u||u.hp<=0)continue;await Promise.all([combatArtReady({species:byId('381'),shiny:u.shiny}),combatArtReady({species:byId('381'),sunWrath:{active:true},shiny:u.shiny})]);if(battle!==current)return;const reduced=reducedMotion();$('#fx').innerHTML=`<div class="sun-wrath-scene ${reduced?'wrath-reduced':''}" role="status"><i class="wrath-tide"></i><i class="wrath-corona"></i><div class="wrath-forms"><img class="wrath-calm" src="${combatArtSrc({species:byId('381'),shiny:u.shiny})}" alt="Solmola before transformation"><img class="wrath-awakened" src="${combatArtSrc({species:byId('381'),sunWrath:{active:true},shiny:u.shiny})}" alt="Solmola in Sun God’s Wrath form"></div>${Array.from({length:12},(_,i)=>`<i class="wrath-spark" style="--n:${i}"></i>`).join('')}<div class="wrath-caption"><b>SUN GOD’S WRATH</b><span>${escapeHTML(unitName(u))} awakens · all six stats +25%</span></div></div>`;blip(220);await delay(reduced?350:2200);if(battle!==current)return;$('#fx').innerHTML='';renderBattle();}}
async function animateResult(who,result,move){
 const current=battle;if(!current)return;await signatureArtReady(move);if(battle!==current)return;current.typeFeedback=move?.power&&!result.missed&&!result.skipped&&!result.immune?{value:result.effectiveness??1,type:move.type_id,who}:null;paintTypeFeedback();const visual=move||{id:0,type_id:result.messages?.some(t=>/poison/i.test(t))?'POISON':result.messages?.some(t=>/burn/i.test(t))?'FIRE':'NORMAL',power:0,effects:[]},spec=effectSpec(visual,result),enemy=$('.enemy-art'),viewport=$('#viewport');
 const self=!!result.skipped||!!result.selfDamage||!move||['SELF','ACTIVE_SIDE'].includes(move.target),enemyTarget=who==='player'?!self:self;
 const target=enemyTarget?$('.enemy-zone'):$('.battle-bottom>.combat-hud'),source=who==='enemy'?$('.enemy-zone'):$('.battle-bottom>.combat-hud'),v=viewport.getBoundingClientRect(),r=target?.getBoundingClientRect(),sr=source?.getBoundingClientRect(),x=r?r.left+r.width/2-v.left:v.width/2,y=r?r.top+r.height/2-v.top:v.height*.4,dx=self?0:sr.left+sr.width/2-v.left-x,dy=self?0:sr.top+sr.height/2-v.top-y;
 $('#fx').innerHTML=`<div class="fx-anchor" style="left:${x}px;top:${y}px;--source-x:${dx}px;--source-y:${dy}px;--travel-angle:${Math.atan2(-dy,-dx)*180/Math.PI}deg">${effectHTML(visual,{...result,targetArt:combatArtSrc(enemyTarget?current.enemies[current.index??0]:current.player)})}</div>`;
 if(spec.hit&&move?.power&&who==='enemy')enemy?.classList.add('charging');
 const hitTime=Math.round(spec.duration*spec.impact);await delay(reducedMotion()?0:hitTime);if(battle!==current)return;
 enemy?.classList.remove('charging');if(result.damage||result.selfDamage){(enemyTarget?enemy:target)?.classList.add(enemyTarget?'hit':'hud-impact');if(result.critical)viewport.classList.add('power-hit');blip(who==='enemy'?180:620);}else blip(490);
 await drainHealth(result);if(battle!==current)return;await delay(reducedMotion()?90:Math.max(120,spec.duration-hitTime-((result.hpChanges||[]).some(h=>h.before!==h.after)?760:0)));enemy?.classList.remove('hit');target?.classList.remove('hud-impact');viewport.classList.remove('power-hit');$('#fx').innerHTML='';if(result.transforms?.length)await animateWrath(result.transforms);
}

async function battleTurn(action){if(!battle||battle.busy||battle.finished||modal)return;const b=battle,p=b.player,e=b.enemies[b.index];if(!['heal','wait'].includes(action)&&(!p.moves[action]||!moveUsable(p,p.moves[action])))return;if(action==='heal'&&(!state.poultices||p.hp>=p.maxHp))return;b.commandMenu=null;b.busy=true;renderBattle();
 // Trainer-equipped moves stay attached to the supplied roster.
 const pool=e.moves.filter(m=>moveUsable(e,m));const em=pool.length?pool[Math.floor(b.random()*pool.length)]:null;const pm=['heal','wait'].includes(action)?{priority:10}:p.moves[action];const order=em?turnOrder(p,e,pm,em,b.random):['player'];
 for(const who of order){if(!battle||b.finished)break;let result;if(who==='player'&&action==='wait'){p.actedThisRound=true;result={damage:0,messages:[`${unitName(p)} waits.`]};}else if(who==='player'&&action==='heal'){state.poultices--;p.actedThisRound=true;const before=captureHealth(p);const n=heal(p);result={damage:0,messages:[`Poultice restored ${n} HP.`],hpChanges:healthChanges(before,p)};refresh();}else{const actor=who==='player'?p:e,target=who==='player'?e:p,m=who==='player'?pm:em;result=applyMove(actor,target,m,b.random);}
  holdBeforeImpact(result);b.log=result.messages.join(' ');b.history.push(`Round ${b.round}: ${escapeHTML(b.log)}`);renderBattle();await animateResult(who,result,who==='player'&&!['heal','wait'].includes(action)?pm:who==='enemy'?em:null);await delay(300);
  if(e.hp<=1){if(!b.defeats.some(d=>d.index===b.index))b.defeats.push({index:b.index,level:e.level,expMultiplier:defeatExpMultiplier(e),participants:[...b.participants]});if(b.index===b.enemies.length-1){b.finished=true;await endBattle(true);return;}b.log=`Geoffrey withdraws ${e.species.name} at 1 HP. ${b.enemies[b.index+1].species.name} enters the test.`;b.history.push(b.log);$('.enemy-art')?.classList.add('withdraw');await delay(reducedMotion()?80:400);b.index++;const entry=enterAbility(b.enemies[b.index],p,{party:b.enemies.slice(b.index),field:p.field||{}});if(entry.length)b.history.push(entry.join(' '));await enemySendOut();break;}
  if(p.hp<=1){b.finished=true;await endBattle(false);return;}
 }
 const before=captureHealth(p,e);const end=cleanupRound(p,e,b.random);if(end.length){const result={messages:end,hpChanges:healthChanges(before,p,e)};holdBeforeImpact(result);b.log=end.join(' ');b.history.push(b.log);renderBattle();await animateResult('player',result,null);}if(e.hp<=1&&b.enemies[b.index]===e){if(!b.defeats.some(d=>d.index===b.index))b.defeats.push({index:b.index,level:e.level,expMultiplier:defeatExpMultiplier(e),participants:[...b.participants]});if(b.index===b.enemies.length-1){b.finished=true;await endBattle(true);return;}b.index++;const entry=enterAbility(b.enemies[b.index],p,{party:b.enemies.slice(b.index),field:p.field||{}});if(entry.length)b.history.push(entry.join(' '));await enemySendOut();}if(p.hp<=1){b.finished=true;await endBattle(false);return;}b.round++;b.busy=false;if(p.moves.every(m=>m.left<=0)){b.log='No PP remains. Concede the practice and rest before another attempt.';}renderBattle();
}
async function endBattle(won){const b=battle;if(!b)return;b.busy=true;b.finished=true;if(modal)closeModal();hideMoveDetails();b.log=won?'Geoffrey yields. Both partners are safe. You passed the assessment.':'Geoffrey stops the assessment. Your partner is safe; no life is lost.';renderBattle();await delay(1100);if(won){const first=!state.test;state.test=true;if(!commitRewards(b,b.defeats||[],{kind:'practice',first})){if(first)state.test=false;b.finished=false;b.busy=false;renderBattle();return;}}if(!won&&state.binocularBattles>0&&!closeBinocularBattle(b))return;hideBattleSurface();refresh();persist();if(won)showRewards();else showDialogue([line('Instructor Geoffrey de Warenne','Better to stop here than learn this lesson on the road. Rest, think about your moves, and come back.','TRN-C01-001')]);}
function about(){openModal('About this slice',`<p><b>v0.90.22 · Training and Rapids:</b> Ten active Mark effects, ten permanent growth-tonic doses, batch level tonics, expanded status lessons, automatic Speed races with 10% luck, and menus that keep your place.</p><p><b>v0.90.21 · Uncapped catch-up XP:</b> Stronger opponents give increasing EXP with no level-gap ceiling. Rivet’s Warbond and Binoculars support full catch-up rewards; a level 1 defeating a level 150 with Warbond gains 4,930 EXP.</p><p><b>v0.90.20 · Clean shiny palettes:</b> All 478 Abyssals have family colour palettes with clean outlines, natural shading and original transparency. Existing shinies update automatically; shiny portraits stay shiny in your menus.</p><p><b>v0.90.19 · The real-world finale:</b> Willowmere’s memorial and two inherited partners, the Peach Grove guardians, artistic Cayfen, Sporefall’s allied double battle, alabaster Ramelle and the mirror threshold. Every eligible family can be obtained by the eighth leader; split branches evolve from their wild bases.</p><p><b>v0.90.16 · Faces of the expedition:</b> Correct companion and post-battle portraits, thirteen restored full-body trainer figures, full-body Khalid and a heavier, harsher Canon Fatima.</p><p><b>v0.90.15 · Quickbite and Angling:</b> Stronger opening Quickbite odds with rapid falloff; immediate keeper submission and a saved full-day fishing cooldown.</p><p><b>v0.90.14 · Glass Scars:</b> Vitrified lightning craters, worn mountain stairs, a detailed broken cart, natural lightning forks and repeatable Stormcatch shifts with a timing demonstration.</p><p><b>v0.80 · The stewards of the old court:</b> Restore linked water channels, balance opposing guardians and deduce a six-Mark oath from the ruins. Six Common Cause road companies contest the expedition, with Darius and Sir Hugh at the inner road. The thirteen cats’ Marks of Honour describe their care for each type and the balance of its element. Hugh and Agnes have new portraits and matching walking art.</p><p><b>v0.70 · The mountain and the side roads:</b> All 69 side-path trainer portraits now match the established illustration style, with complete figures and supported equipment. Dedicated mountain terrain, trail scenery, summit cairns, fossil beds, a reanimation workbench and four travellers replace the temporary drawings. Existing encounters, quests, saves and growth remain intact.</p><p><b>v0.69 · Windscar Crossing:</b> Philomere to Cybressa is now a seven-screen mountain journey through foothills, descending mine passages, ascending galleries, an exposed pass and eastern scree. Optional Crystal Hollow and Summit Cairns add separate habitats and one-time supplies. Restore the summit cairns to encounter Caelynx, or assist a Dawn Bloom fossil scholar and choose one of four ancient Abyssals to revive. Ground and Rock species dominate new day/night tables, with ridge birds and cold-adapted summit wildlife.</p><p><b>v0.68 · Grow together:</b> Captured Abyssals need a level gained with Aimon before a level evolution. Each partner can evolve only once at each level, including when it was caught above several evolution thresholds.</p><p><b>v0.67 · Records of the side roads:</b> Read 45 short site records explaining each place’s former use, wartime damage and the people affected. Expanded clues explain the repair and its consequences, with shorter dialogue pages and full notes beside the controls.</p><p><b>v0.66 · The places behind the war:</b> All fifteen side expeditions now have historical signposts, clearer repair clues, named mechanism controls and individual warden conversations. Quest reminders and the journal point to your next unfinished step.</p><p><b>v0.65 · Trainer portrait corrections:</b> 49 of the 69 side-path battle portraits now use the established anime trainer style, complete full-body framing and physically held shields and weapons. The remaining 20 retain their previous artwork pending a later correction. <a href="trainer-art.html">Review the corrected portraits</a>.</p><p><b>v0.64 · The Side-Path Companies:</b> 69 individual trainers now have matching battle portraits and directional walking art. First Light wears European crusader armour; Dawn Bloom draws on Salah ad-Din’s armies. <a href="trainer-art.html">Review the trainer artwork</a>.</p><p><b>v0.63 · The Court Without a Crown:</b> Follow the old royal road from Rivercause Road after resolving Philomere. Free thirteen unique roaming guardians from an orb and sceptre. The shared encounter chance is 1%; guardians may flee each round and never return after capture or death. Verdantyr lives in the Verdant Understory off Orchard Canopy.</p><p><b>v0.61 · Brinelet and Gorgobrine:</b> The approved Poison/Water family appears at the Reed-bed and Backwater fishing jetties, with rare Gorgobrine at Smugglers’ Weir. Brinelet evolves at level 32, preserving earned stats and gaining stronger growth. Miasma has a 33% turn-end chance to badly poison opposing active Abyssals; new poison starts damaging on the following turn. Gorgon’s Breath hits every opposing target with seven streams of venom. Both stages have battle portraits and three-frame directional walking animation.</p><p><b>v0.60 · Expedition prizes, new artwork and route fishing:</b> All fifteen expeditions now grant held items, permanent move lessons, a rare-food recipe, ability attunement, a hidden-ability sigil, a gift companion or a Rivet core. Completed older quests can collect the new prize once. Mercy Chalice doubles medicine, healing moves and drain received, capped at full HP. Eight wooden route jetties offer free local Water encounters after obtaining the rod, and paid contest bait stays in your bag. Steel/Fire Pricklet, Cinderlance and Ferriferno have distinct new designs. The shark family, Solmola’s two forms, Oracle narwhal and final manta have consistent anime-style art and matching directional followers. Solmola’s transformation has its own solar awakening animation. Sixteen custom overworld mechanisms show lantern, water, winch, stone and gate states.</p><p><b>v0.59 · Side expeditions and First Light Salvation:</b> Fifteen side areas now lead through three connected stages with clues, path challenges, lantern, sequence, evidence or weight mechanisms, optional partner assistance and a final decision. Earlier trades, collections, rescue and fishing rewards remain available. Walter freely teaches First Light Salvation to every living Abyssal; it uses the stronger attacking stat, has its own gold seal animation and cannot reduce its target below 1 HP. Turn-end poison and burn still apply.</p><p><b>v0.58 · Fortress rarities and trainer variety:</b> Rimebun appears on all five floors: 3% on floors one to three and 5% deeper down. The last two floors introduce distinct evolved aquatic and ruined-stone rarities. Fortress gatekeepers and town leaders field six Abyssals. Ordinary early-route trainers roll a persistent team of one to four; a lone ace is two levels stronger.</p><p><b>v0.57 · Rivet stand-off:</b> Rivet and its two opponents now have solid positions on the forest path. Approach any of the three for the Help Rivet prompt, press A to engage, or tap their sprites. Their collision clears permanently after the rescue.</p><p><b>v0.56 · Discovered caravan destinations:</b> Every major town has a caravan hub. Destinations become available after your first visit and remain unlocked in your save. The optional Sunken Fort must also be discovered before travelling there.</p><p><b>v0.55 · Woodland bell gates:</b> Existing Rim-fragment saves can continue through the repaired lantern gate. Carved Crown, Rim and Clapper pillars now show animated flames and warm light. Moss-covered ancient gate doors retract into their stone housings when unlocked.</p><p><b>v0.53 · Approved aquatic families and Android:</b> Snubling, Narlit, Solmola and Finlet now appear as rare aquatic encounters and in fishing. Their evolutions have special-focused learnsets, individual growth and active abilities. Rivet can use a Chitin Core to become Carapex and Elytrarch. Download and upload saves to continue between browser and Android.</p><p><b>v0.52 · Portable saves and special Fighting:</b> Download or upload full expedition files from the title or field menu. Five new special Fighting attacks support the Cindertap, Palmote, Knollop and Anvilip families. Review the redesigned aquatic creatures and praying-mantis Rivet branch at <a href="approval-concepts.html">the concept gallery</a>; the approved forms are now in the game.</p><p><b>v0.51 · Bell guardians and angling podium:</b> One shared Steel base branches through six relic cores into twelve approved armoured forms. Warbond doubles participant EXP, including binocular participation. Find Rivet in Ember Quarry or Relic Crags, or help a cornered Rivet in Briarbell Wood’s optional double battle. Recover guarded fragments across three screens and solve the lantern gate to earn a core from Briarbell Wood’s bell-restoration quest and use it from Bag → Evolution.</p><p><b>v0.49 · Cybressa:</b> Rivercause Road, a warehouse investigation and grain-allocation choice, the civic fort and its level-42 provost, Backwaters, Smugglers’ Weir and Salt Flats side quests, personal watercraft, paid caravan travel, and repeatable Trial Contracts with a Training Draught shop. The soldier’s rescue gift now starts with a three-type selection; all three fixed offers match at least one selected type.</p><p>A standalone browser journey from Civeton through Dorelem and Philomere to Cybressa, based on the story Bible and supplied artwork.</p><ul class="notes-list"><li>Existing Aimon, William, Walter and Geoffrey portraits; existing Scarimp, Calibrit, Ruffurn, Pennkit and Mottlet art. First-person battle, with only the enemy rendered.</li><li>Story follows the opening chapter and the Dorelem, Philomere and Cybressa story beats, with the memorial and childhood hill. Dialogue wording, pixel scenery and room layouts are prototype authoring. Dialogue uses speaker busts; full-body trainer art appears only before the first send-out. Matilda’s portrait is absent from the supplied artwork, so her assessment appears as text.</li><li>Species and moves come from supplied data, with the agreed starting-stat, level, healing and Brave Blow PP adjustments. The standard 18-type chart applies to damaging moves. Taming uses species catch rates (150 fallback), a level penalty of 1 / (1 + (level / 20)²), and four capture checks. Hearty Rations sold from Dorelem have twice Trail Bread’s capture strength; species catch rates and the final capture binding remain unresolved. Starter Lv. 8, direct base-stat initialization, damage, critical hits, confusion timing and contact/sound classifications are demonstration bindings. Authored abilities and held items are active; the wider campaign remains outside this build.</li><li>Geoffrey uses the authored Pennkit Lv. 8 and Mottlet Lv. 10. Mottlet’s supplied legal moves are defensive; this prototype does not give it an invented attack.</li><li>Practice partners stop at 1 HP. Wilderness combat can kill ordinary partners and consume original starter lives. The March and new roads include authored day/night encounters, food taming, trainer challenges and town reserve access. Victories show EXP, seeded six-stat level-ups and exact-level move choices. The 25 EXP level-gap formula is provisional play-test tuning. Evolution and species abilities are implemented; the wider campaign remains unimplemented. Wild combat is lethal; original starter lives follow the three-life return rule.</li><li>The browser expedition autosaves locally, including wild battle RNG, food use, captures and starter lives. Reload resumes the committed state; Restart explicitly clears it. Three independent browser slots preserve expeditions locally; these are not the final campaign Ironman/crash-recovery contract. The phase clock pauses while the page is hidden or closed.</li></ul>`);}
document.addEventListener('keydown',e=>{if(e.key.toLowerCase()!=='f'||e.repeat||!state.begun||state.wiped||dialogue||modal||battle||presentationLocked||e.target.matches?.('input,textarea'))return;const j=jettyFor(room),spot=room==='anglersReach'?spots.find(s=>(s.id==='fishing-cast'||s.id==='fishing-cast-north')&&Math.abs(s.x-player.x)+Math.abs(s.y-player.y)<=1):j&&Math.abs(j.x-player.x)+Math.abs(j.y-player.y)<=1?j:null;if(spot){e.preventDefault();castFishingLine();}});
function controls(){openModal('Explore Civeton',`<p><b>Desktop:</b> WASD or arrows to walk. E or Space to interact with the tile ahead. Enter continues dialogue. Shift runs at twice walking speed. F casts when standing at a fishing jetty. The Run button toggles running for keyboard, touch and tap-to-walk. M or Escape opens the menu; Escape closes it.</p><p><b>Handheld:</b> Run toggles double-speed travel. Start opens the field menu, Select opens the journal, A confirms or interacts and B goes back. The D-pad walks or selects visible commands. Use the directional buttons or tap a location label to walk to it and interact. The map follows Aimon on smaller screens. Tap the i beside a battle move for its mechanics; the main move button uses it.</p><p>Walk north into a dark doorway to enter a house, or tap its label. Inside, speak to Pate’s mother or Trade’s grandfather, or inspect supplies; walk south over the exit mat to leave. The shrine, childhood hill, shop and memorial are optional visits. Walk over a marked road crossing to enter or leave an area, or tap its label. After the test, the east road leads to Civeton March and a food-taming demonstration. Active partners can be changed from Expedition; reserve access stays with Walter in Civeton.</p><p>Your living lead Abyssal follows you. Tap a direction briefly to turn without walking, then use E, Space or A to talk to the partner behind you. You can also tap its overworld sprite. Change your follower with the Lead button in Expedition. Conversations show its mood and larger portrait; low HP or a status condition changes how it feels.</p><p>The Journal tracks your objective. Sound enables short interface tones only.</p><div class="modal-actions"><button id="help-notes">Prototype notes</button></div>`);$('#help-notes').onclick=about;}
function closestInteract(){if(player.step)return null;if(campaignArea(room)?.stage<2&&player.x===43&&player.y>=16&&player.y<=18)return spots.find(s=>s.action==='side-campaign-gate')||null;if(relicRescueNearby(state,room,player))return spots.find(s=>s.id==='relic-stand-off')||null;const [dx,dy]=dirs[player.facing];const animal=farmActors(room).find(a=>a.x===player.x+dx&&a.y===player.y+dy);if(animal)return animal;if(companion.visible&&!companion.step&&companion.x===player.x+dx&&companion.y===player.y+dy)return {id:'party-companion',label:unitName(companion.unit)};return spots.find(s=>s.x===player.x+dx&&s.y===player.y+dy||s.routeSign&&signContains(s,player.x+dx,player.y+dy))||spots.find(s=>s.x===player.x&&s.y===player.y);}
const dirs={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]};
function companionConversation(){const u=lead();if(!u||player.step||companion.step)return;syncCompanion(companion,u,player,room,blocked);if(!companion.visible||Math.abs(companion.x-player.x)+Math.abs(companion.y-player.y)>1)return;const response=talkToCompanion(u,{night:phaseAt(phaseElapsed)==='NIGHT',indoors:!['town','march',...Object.keys(NEW_MAPS)].includes(room)});companion.facing=player.x>companion.x?'right':player.x<companion.x?'left':player.y>companion.y?'down':'up';companion.reactionUntil=performance.now()+1800;showDialogue([{speaker:unitName(u),text:response.text,abyssalId:u.species.id,abyssalUnit:u,mood:response.label}]);persist();}
