function tamingDialogue(){showDialogue([line('Roadside bystander',state.tamingTaught?'Back again? I can show you the bread trick once more.':'A new partner, and already marching east? Before you go, let an old traveller show you how to make another friend.','bystander'),line('Aimon','You can tame the wild ones with food?','CHR-AIMON'),line('Roadside bystander','Food, patience, and restraint. Weaken one carefully if you must, but leave it alive. You cannot make a friend of a corpse.','bystander'),{...line('Roadside bystander','Watch my partner make a careful strike. Then I’ll offer Trail Bread. This is my demonstration; your supplies stay in your bag.','bystander'),choices:[{text:'Watch the demonstration',action:startLesson},{text:'Not yet',action:()=>{}}]}]);}
function startLesson(){if(battle)return;const p=instance(byId('018'),8,[moveId(8)]),e=instance(byId('010'),5,[moveId(8)]);e.hp=Math.min(22,e.maxHp);battle={kind:'lesson',player:p,enemies:[e],index:0,round:1,random:rng(211),lessonStep:0,phase:'ready',sendOut:true,busy:true,finished:false,log:'The bystander’s Rouncolt faces a tired Pennkit. Watch its HP.',history:[]};initializeBattleAbilities(battle);showBattleSurface();renderBattle();const b=battle;b.artReady=false;renderBattle();void battleArtReady(p,e).then(()=>{if(battle!==b)return;b.artReady=true;renderBattle();return delay(reducedMotion()?100:850);}).then(()=>{if(battle!==b)return;b.sendOut=false;b.busy=false;renderBattle();});}
async function lessonStep(){const b=battle;if(!b||b.kind!=='lesson'||b.busy)return;b.busy=true;if(b.lessonStep===0){const m=b.player.moves[0],result=applyMove(b.player,b.enemies[0],m,b.random);b.log=result.messages.join(' ')+' It is still alive.';renderBattle();await animateResult('player',result,m);b.lessonStep=1;b.busy=false;renderBattle();return;}const result=resolveCapture(b.enemies[0],rng(1));b.log='The bystander offers his bread. Watch the Abyssal approach.';renderBattle();await foodAnimation(result);hideBattleSurface();const first=!state.tamingTaught;state.tamingTaught=true;if(first){state.bread+=2;state.smoke+=1;}refresh();persist();showDialogue([line('Roadside bystander','There. It ate, then chose to come closer. Wild ones may refuse, and a failed offer still uses the food. Keep enough supplies to get home.','bystander'),line('Roadside bystander','Use Run to escape wild encounters: it succeeds four times out of five, unless a trapping effect holds your partner. Outside the lesson there is no referee. Ordinary partners die at zero HP. Your first partner has its three original lives; that is no reason to waste them.','bystander'),line('Roadside bystander',first?'Take two pieces of Trail Bread and a Smoke Bomb. The smoke guarantees escape from enemy trainers. Civeton’s shop can replenish them.':'You can always turn back to Civeton. Walter can rest your living partners and arrange your reserve.','bystander')]);}
function routeGuide(){const expedition=campaignArea(room);const history=ORCHARD_ROUTES[room]?orchardHistoryHTML(room,escapeHTML):expedition?campaignRecordHTML(expedition.c,expedition.stage,escapeHTML)+(state.sideCampaigns?.[expedition.c.key]?.claimed?'<p><b>Your work here:</b> '+escapeHTML(campaignReminder(state,expedition.c))+'</p>':'<p><b>Where to look:</b> Examine the '+['trail evidence','repair inscription','site register'][expedition.stage]+' beside the path. '+escapeHTML(expedition.c.objective[expedition.stage])+'.</p>')+'<hr>':NEW_MAPS[room]?.passKind?passRecordHTML(room,escapeHTML)+'<p><b>'+escapeHTML(mountainQuestHint(state,room))+'</b></p>':'';if(expedition&&!NEW_MAPS[room].grass?.length){openModal(roomName(room)+' · signpost',history+'<p>No wild Abyssals roam this clearing. Follow the cleared trail to explore farther.</p>');return;}const notices=NEW_MAPS[room]?.routeNotices||[],detours=AREA_GATES[room]?.filter(g=>NEW_MAPS[room]?.sidePaths?.some(p=>p.gateId===g.id))||[];const stage=routeStage(room);const phase=phaseAt(phaseElapsed),table=areaRoute().tables.find(t=>t.phase===phase),low=Math.min(...table.slots.map(s=>s.min_level)),high=Math.max(...table.slots.map(s=>s.max_level));openModal(roomName(room)+' · signpost',`${history}<p>${stage?'Stretch '+stage.stage+' / '+stage.count+' · ':''}Wild levels ${low}–${high}. ${CAVE_FLOORS.some(f=>f.room===room)?'Wild encounters occur on the shallow flooded flagstones. Dry stone walks are safe; deep blue water is impassable.':routeStage(room)?.base==='tunnels'?'Encounters can occur throughout the sewer.':biomeEncounterHint(room)} Return to the last town for rest and supplies.</p><p>${phase==='DAY'?'Daytime sightings':'Night-time sightings'}</p><table class="encounter-table"><thead><tr><th>Abyssal</th><th>Wild level</th><th>Sightings</th></tr></thead><tbody>${table.slots.map(s=>`<tr><td>${byId(s.species_id).name}</td><td>${s.min_level}–${s.max_level}</td><td>${s.weight>=20?'Common':s.weight>=8?'Uncommon':'Rare'} · ${Number(s.weight.toFixed(2))}%</td></tr>`).join('')}</tbody></table><p>Watch the verges. Some creatures are seen much less often than others.</p>${detours.length?'<p><b>Side paths:</b> '+detours.map(g=>escapeHTML(g.label)+' — '+(g.y<15?'north':g.y>19?'south':g.x<24?'west':'east')+' side path').join(' · ')+'.</p>':''}${notices.filter(n=>!['sluice-notice','veilroot-sign'].includes(n.id)).map(n=>'<p>'+escapeHTML(n.label)+'</p>').join('')}${room==='tunnels'?'<p>'+PUZZLE_CLUE+'</p><button id="board-reset-stones" '+(puzzleState(state).solved?'disabled':'')+'>Reset stones</button>':''}${notices.some(n=>n.id==='veilroot-sign')?'<button id="board-fort-history">Read the Sunken Fort history</button>':''}`);$('#board-reset-stones')?.addEventListener('click',()=>{if(rewardTransaction(()=>resetStones(state))){closeModal();toast('The service keeper resets the stones.');}});$('#board-fort-history')?.addEventListener('click',()=>{closeModal();explorationInteract('veilroot-sign');});}
function routeEnd(){if(!state.tamingTaught){stopMovement();toast('Speak to the bystander before leaving the clearing.');return;}stopMovement();if(state.routeComplete){void warp('scrub',3,17,'right');return;}state.routeComplete=true;refresh();persist();showDialogue([line('Dorelem Scrub','The marching road narrows into scrub. Beyond it, the keep at Dorelem controls the way north.'),line('Aimon','Pate and Trade came this way. We’re closer.','CHR-AIMON')],()=>void warp('scrub',3,17,'right'));}
function scrubBoundary(){stopMovement();setPlayer(45,17,'left');openModal('Beyond Dorelem Scrub’s entrance',`<p>The next part of Dorelem Scrub is beyond this play-test boundary. You can walk west over the marked crossing to return to Civeton March.</p>`);persist();}
function partyMenu(atAeric=false){if(battle?.busy)return;const inWild=battle?.kind==='wild';if(battle&&!inWild)return;if(atAeric){for(const u of state.reserve)if(u.hp>0){u.hp=u.maxHp;u.status=null;u.confusion=0;u.stages={};u.moves.forEach(m=>m.left=m.pp);}persist();}openModal(atAeric?'Walter · Expedition and reserve':'Your expedition',`${!inWild?`<button id="rename-character">Character name · ${escapeHTML(state.playerName)}</button>`:''}<p>${inWild?'Changing a living partner uses your action; the wild Abyssal can attack the incoming partner. A required replacement after a death costs no extra action.':'Up to six active partners. Your living lead walks behind you in the overworld; tap its sprite or turn and interact to check its mood. Reserve access is through Walter in town.'}</p><div class="party-list">${state.party.map(u=>`<div class="party-row"><img src="${combatArtSrc(u)}" alt="${escapeHTML(unitName(u))}"><div><b>${escapeHTML(unitName(u))}</b><small>${u.nickname?u.species.name+' · ':''}Lv. ${u.level} · ${u.hp}/${u.maxHp} HP · ${livesRemaining(u)+' '+(livesRemaining(u)===1?'life':'lives')}</small></div><button data-nickname="${u.uid}" ${inWild?'disabled':''}>Nickname</button><button data-lead="${u.uid}" ${u.hp<=0||u===lead()&&!inWild||inWild&&u===battle.player?'disabled':''}>${inWild?'Send out':'Lead'}</button>${atAeric?`<button data-reserve="${u.uid}" ${state.party.filter(p=>p.hp>0).length<=1?'disabled':''}>Reserve</button>`:''}</div>`).join('')||'<p>No active partners remain.</p>'}</div>${atAeric?`<button id="aeric-relearn">Relearn moves · free</button><h3>Reserve · ${state.reserve.length}</h3>${state.reserve.map(u=>`<div class="party-row"><img src="${combatArtSrc(u)}" alt="${escapeHTML(unitName(u))}"><div><b>${escapeHTML(unitName(u))}</b><small>${u.nickname?u.species.name+' · ':''}Lv. ${u.level} · ${u.hp}/${u.maxHp} HP · One life</small></div><button data-nickname="${u.uid}">Nickname</button><button data-withdraw="${u.uid}" ${state.party.length>=6?'disabled':''}>Withdraw</button></div>`).join('')||'<p>No partners in reserve.</p>'}`:''}${state.dead.length?`<p>Memorial record: ${state.dead.map(u=>escapeHTML(unitName(u))).join(', ')}. Lost partners cannot be healed or sent out.</p>`:''}`);
 $('#rename-character')?.addEventListener('click',()=>namePrompt('Character name',state.playerName,name=>{state.playerName=name;persist();partyMenu(atAeric);}));$('#aeric-relearn')?.addEventListener('click',()=>relearnMenu());document.querySelectorAll('[data-nickname]').forEach(el=>el.onclick=()=>{const u=[...state.party,...state.reserve].find(u=>u.uid===el.dataset.nickname);if(u)nicknamePrompt(u,()=>partyMenu(atAeric));});
 document.querySelectorAll('[data-lead]').forEach(el=>el.onclick=()=>{const uid=el.dataset.lead;closeModal();if(inWild)void wildTurn({switchUid:uid});else{state.leadUid=uid;persist();refresh();toast('Expedition lead changed');}});document.querySelectorAll('[data-reserve]').forEach(el=>el.onclick=()=>{const uid=el.dataset.reserve,u=state.party.find(u=>u.uid===uid);if(!u||state.party.length<=1)return;state.party=state.party.filter(u=>u.uid!==uid);state.reserve.push(u);if(state.leadUid===uid)state.leadUid=state.party[0].uid;refresh();partyMenu(true);});document.querySelectorAll('[data-withdraw]').forEach(el=>el.onclick=()=>{const uid=el.dataset.withdraw,u=state.reserve.find(u=>u.uid===uid);if(!u||state.party.length>=6)return;state.reserve=state.reserve.filter(u=>u.uid!==uid);state.party.push(u);state.wiped=!state.party.some(p=>p.hp>0);if(!state.wiped)state.mercyHub=null;persist();refresh();partyMenu(true);});}

// Overworld menu. Battle commands and story dialogs retain their own controls.
function menuBack(action=gameMenu,label='Back to menu'){const bar=document.createElement('div');bar.className='menu-back';const button=document.createElement('button');button.textContent=label;button.onclick=action;bar.append(button);$('.modal').append(bar);}
function expeditionRecovery(){const mercy=!!state.mercyHub;openModal(mercy?'Aimon is spared':'The expedition is lost',`<p>${mercy?'Aimon survives the formal challenge. Lost partners remain lost. Rebuild your expedition through Walter’s living reserves.':'No living expedition partners remain.'}</p><div class="modal-actions">${mercy?`<button id="mercy-reserve" ${state.reserve.some(u=>u.hp>0)?'':'disabled'}>Walter’s reserve</button>`:''}<button id="confirm-restart" class="primary">Restart slice</button></div>`);$('#mercy-reserve')?.addEventListener('click',()=>partyMenu(true));}
function gameMenu(){if(battle||presentationLocked||!state.begun||state.wiped||state.rewardQueue?.length)return;openModal('Field menu',`<div class="menu-profile"><b>${escapeHTML(state.playerName)}</b><span>${escapeHTML(roomName(room))} · ${state.money.toLocaleString('en-GB')} doubloons</span></div><nav class="field-menu" aria-label="Game menu"><button id="menu-abyssals"><b>Abyssals</b><span>${state.party.length} partners · stats and moves</span></button><button id="menu-bag"><b>Bag</b><span>Medicine, food and field supplies</span></button><button id="menu-trainer"><b>Trainer</b><span>Your name and expedition</span></button><button id="menu-types"><b>Type chart</b><span>Weaknesses, resistances and move symbols</span></button><button id="menu-journal"><b>Journal</b><span>Objectives and progress</span></button>${fortForRoom(room)?'<button id="menu-fort-mechanism"><b>Fort mechanism</b><span>Clue and reset</span></button>':''}<button id="menu-save"><b>Save</b><span>Save your expedition</span></button><button id="menu-download-save"><b>Download save</b><span>Continue on another browser or device</span></button><button id="menu-upload-save"><b>Upload save</b><span>Open an expedition from a JSON file</span></button><button id="menu-nursery"><b>Nursery & eggs</b><span>Egg Pouch · ${state.nursery?.eggs?.length||0}/3 · ${state.nursery?.eggs?.some(e=>e.remaining===0)?'ready to hatch':'walk to hatch'}</span></button><button id="menu-rematches"><b>Spared leaders</b><span>Repeatable trained-team rematches</span></button><button id="menu-revolt"><b>The Common Cause</b><span>Peasant revolt · accounts and sanctuary clues</span></button><button id="menu-outcomes"><b>Choice rewards</b><span>Your decisions and supplies received</span></button><button id="menu-settings"><b>Settings</b><span>Sound and controls</span></button></nav><div class="modal-actions"><button id="menu-resume" class="primary">Return to game</button></div>`);$('.modal').classList.add('field-menu-modal');$('#menu-nursery').onclick=nurseryMenu;$('#menu-rematches').onclick=leaderRematchMenu;$('#menu-outcomes').onclick=choiceRewardsMenu;$('#menu-revolt').onclick=revoltJournalMenu;$('#menu-abyssals').onclick=abyssalMenu;$('#menu-bag').onclick=bagMenu;$('#menu-trainer').onclick=trainerMenu;$('#menu-types').onclick=typeChartMenu;$('#menu-journal').onclick=journalMenu;$('#menu-fort-mechanism')?.addEventListener('click',()=>fortMechanism(fortForRoom(room).key));$('#menu-save').onclick=saveMenu;$('#menu-download-save').onclick=downloadSaveMenu;$('#menu-upload-save').onclick=uploadSaveFile;$('#menu-settings').onclick=settingsMenu;$('#menu-resume').onclick=closeModal;$('#menu-abyssals').focus();}
function normalizeSummaryArt(){document.querySelectorAll('[data-summary-art]').forEach(im=>{const id=im.dataset.summaryArt,u=[...state.party,...state.reserve,...(state.dead||[])].find(u=>u.uid===im.dataset.summaryUid),subject=u||{species:{id},shiny:im.dataset.summaryShiny==='true'};void combatArtReady(subject).then(()=>{if(im.isConnected&&im.dataset.summaryArt===id)im.src=combatArtSrc(subject);});});}
function abyssalMenu(){openModal('Your Abyssals',`<p>${state.party.length} / 6 active partners. Reserve access is with Walter in town.</p><div class="summary-list">${state.party.map(u=>`<button class="summary-choice" data-summary="${u.uid}"><img data-summary-art="${u.species.id}" data-summary-uid="${escapeHTML(u.uid)}" data-summary-shiny="${u.shiny===true}" src="${combatArtSrc(u)}" alt=""><span><b>${escapeHTML(unitName(u))}</b><small>${u.species.name} · Lv. ${u.level}<br>${u.hp} / ${u.maxHp} HP · ${u.originalStarter?u.lives+' lives':'One life'}</small></span><span>Summary</span></button>`).join('')||'<p>Choose your first partner with William to begin your expedition.</p>'}</div>${state.party.length?'<button id="menu-manage-party">Manage expedition</button>':''}<p class="growth-report-link"><a href="growth-report.html" target="_blank" rel="noopener">Full Abyssal growth report</a> · <a href="move-lab.html" target="_blank" rel="noopener">Move Studio and learnset audit</a> · <a href="follower-catalogue.html" target="_blank" rel="noopener">Abyssal field guide</a></p>`);normalizeSummaryArt();document.querySelectorAll('[data-summary]').forEach(el=>el.onclick=()=>partnerSummary(el.dataset.summary));$('#menu-manage-party')?.addEventListener('click',()=>{partyMenu();menuBack(abyssalMenu,'Back to Abyssals');});menuBack();}
function partnerSummary(uid,tab='stats'){const u=state.party.find(u=>u.uid===uid);if(!u){abyssalMenu();return;}const labels={attack:'Attack',defence:'Defence',sp_attack:'Special Attack',sp_defence:'Special Defence',speed:'Speed'};const i=state.party.indexOf(u);openModal('Partner summary',`<div class="summary-hero"><img data-summary-art="${u.species.id}" data-summary-uid="${escapeHTML(u.uid)}" data-summary-shiny="${u.shiny===true}" src="${combatArtSrc(u)}" alt="${escapeHTML(unitName(u))}"><div><h3>${escapeHTML(unitName(u))}</h3><p>${u.species.name} · Lv. ${u.level}<br>${u.species.types.join(' / ')}</p><span>${u.originalStarter?`${u.lives} original lives remaining`:'One life · permanent death at zero HP'}</span></div></div>${abilitySummaryHTML(u)}<p class="summary-exp">EXP ${Math.min(u.exp||0,100)} / 100${u.level>=200?' · Level cap':''}<progress max="100" value="${Math.min(u.exp||0,100)}"></progress></p><div class="summary-tabs" role="tablist" aria-label="Partner details"><button id="summary-stats" role="tab" aria-selected="${tab==='stats'}">Stats</button><button id="summary-moves" role="tab" aria-selected="${tab==='moves'}">Moves</button><button id="summary-tree" role="tab" aria-selected="${tab==='tree'}">Learn tree</button></div>${tab==='stats'?`<div class="stat-flip-control"><button id="summary-flip" aria-pressed="false" aria-controls="summary-growth">Flip to growth rates</button><span id="summary-face" role="status">Current stats</span></div><div class="stat-flip"><div class="stat-flip-inner"><section class="stat-face stat-front" aria-label="Current stats"><div class="stat-grid"><div><span>HP</span><b>${u.hp} / ${u.maxHp}</b></div>${Object.entries(labels).map(([key,label])=>`<div><span>${label}</span><b>${Math.floor(u.stats[key]*stageMultiplier(u.stages[key]))}${u.stages[key]?` <small>(${u.stages[key]>0?'+':''}${u.stages[key]})</small>`:''}</b></div>`).join('')}</div></section><section id="summary-growth" class="stat-face stat-back" aria-label="Base growth percentages" aria-hidden="true" inert>${growthSummaryHTML(u)}</section></div></div><p class="summary-note">${u.originalStarter||u.lifeEmbersReceived?'Filled diamond pips in battle show remaining lives. Your partner returns at 10% HP while a life remains. The final loss is permanent.':'This partner has one life. A rare Life Ember can add one; resurrection is available through the Civeton memorial.'}</p>`:tab==='tree'?learnTreeHTML(u):`<div class="summary-moves">${u.moves.map(m=>`<article><div><b>${m.name}</b><span>${m.left} / ${m.pp} PP</span></div><small>${m.type_id} · ${m.category==='STATUS'?'Status':m.category==='SPECIAL'?'Special':'Physical'} · ${m.power?'Power '+m.power:'No damage'} · ${m.accuracy==='ALWAYS'?'Always hits':'Accuracy '+(m.accuracy??100)+'%'} · Priority ${m.priority||0}</small><p>${m.effect_text||'No additional effect.'}</p></article>`).join('')}</div>`}<div class="summary-nav"><button id="previous-partner" ${i===0?'disabled':''}>Previous</button><span>${i+1} / ${state.party.length}</span><button id="next-partner" ${i===state.party.length-1?'disabled':''}>Next</button></div><button id="summary-nickname">Nickname</button>${!battle&&eligibleEvolutions(u,state).length?'<button id="summary-evolve">Evolve now</button>':''}`);normalizeSummaryArt();$('#summary-flip')?.addEventListener('click',()=>{const card=$('.stat-flip'),flipped=card.classList.toggle('is-flipped'),button=$('#summary-flip');button.setAttribute('aria-pressed',String(flipped));button.textContent=flipped?'Flip to current stats':'Flip to growth rates';$('#summary-face').textContent=flipped?'Base growth percentages':'Current stats';for(const [selector,hidden] of [['.stat-front',flipped],['.stat-back',!flipped]]){const face=$(selector);face.setAttribute('aria-hidden',String(hidden));face.inert=hidden;}});$('#summary-stats').onclick=()=>partnerSummary(uid,'stats');$('#summary-moves').onclick=()=>partnerSummary(uid,'moves');$('#summary-tree').onclick=()=>partnerSummary(uid,'tree');$('#previous-partner').onclick=()=>partnerSummary(state.party[i-1].uid,tab);$('#next-partner').onclick=()=>partnerSummary(state.party[i+1].uid,tab);$('#summary-nickname').onclick=()=>nicknamePrompt(u,()=>partnerSummary(uid,tab));$('#summary-evolve')?.addEventListener('click',()=>{if(!rewardTransaction(()=>state.rewardQueue.push({kind:'evolve-check',uid:u.uid})))return;closeModal();showRewards();});menuBack(abyssalMenu,'Back to Abyssals');}
function bagMenu(pocket='medicine'){const pockets={medicine:'Medicine',food:'Food',field:'Field items',held:'Held items',evolution:'Evolution',key:'Keepsakes',training:'Training'};const canHeal=state.party.some(u=>u.hp>0&&u.hp<u.maxHp);openModal('Your bag',`<div class="bag-pockets" role="tablist" aria-label="Bag pockets">${Object.entries(pockets).map(([key,label])=>`<button data-pocket="${key}" role="tab" aria-selected="${key===pocket}">${label}</button>`).join('')}</div><div class="bag-item">${pocket==='training'?trainingBagHTML():pocket==='held'?heldBagHTML():pocket==='evolution'?evolutionBagHTML():pocket==='medicine'?specialistBagHTML(state,true)+lifeEmberBagHTML()+`<div class="bag-item-heading"><h3>Poultice</h3><b>× ${state.poultices}</b></div><p>Restores 50% of maximum HP, up to 50 HP to a living partner. Cannot revive a lost partner.</p><button id="bag-use-poultice" class="primary" ${!state.poultices||!canHeal?'disabled':''}>Use on a partner</button>`:pocket==='food'?specialistBagHTML(state)+`<div class="bag-item-heading"><h3>Trail Bread</h3><b>× ${state.bread}</b></div><p>Offer food to a living wild Abyssal in combat to try to recruit it. A refused offer still consumes the food.</p><p>Higher-level Abyssals are harder to recruit.</p><div class="bag-item-heading"><h3>Hearty Ration</h3><b>× ${state.heartyFood||0}</b></div><p>Twice Trail Bread’s capture strength. Sold in Dorelem and later towns for 400 doubloons. Use the food commands during a wild encounter; refused offers consume one ration.</p><div class="bag-item-heading"><h3><img class="capture-food-icon" src="${FRESH_MEAT.icon}" alt="">Fresh Meat</h3><b>× ${state.freshMeat||0}</b></div><p>6× Trail Bread’s capture strength. Sold in Cybressa and Cossenne for 1,200 doubloons. A refused offer consumes one portion.</p><div class="bag-item-heading"><h3>Patient Ration</h3><b>× ${state.patientRations||0}</b></div><p>Sold in Cossenne for 800 doubloons. Capture strength rises from 1× at the start of battle to 4× after 30 elapsed turns. Each refused offer consumes one.</p><div class="bag-item-heading"><h3>Winter Preserve</h3><b>× ${state.winterPreserves||0}</b></div><p>3× capture food strength for Grass/Bug partners; 2× otherwise. ${state.questUnlocks?.winterRecipe?'Recipe available at town shops.':'Complete Roots for the Hungry to unlock the recipe.'}</p><div class="bag-item-heading"><h3>River Bait</h3><b>× ${state.riverBait||0}</b></div><p>Purchased with contest entry and kept in your bag. Use for Water-type catches in the competition or at the wooden route jetties.</p>`:pocket==='field'?fieldBagHTML()+`<h3>Fishing rod · ${state.sideAdventures?.fishing?.rod?'Owned':'Not yet received'}</h3><p>Cast from the Angler’s Reach jetty. River Bait × ${state.riverBait||0} · Water types only, during your entered competition.</p>`:(state.trade?`<div class="bag-item-heading"><h3>Trade’s note</h3><b>× 1</b></div><p>Entrusted to you by Trade’s grandfather.</p><blockquote>“Don’t follow us.”</blockquote><p>Four words. No explanation.</p>`:(state.paladinCourt?.released?'':'<p>No keepsakes collected yet.</p>'))+courtKeepsakeHTML()+(state.cossenne?.expeditions?.grove?.keepsake?'<h3>Pilgrim Bell</h3><p>Recovered from the Old Pilgrim Grove. A keepsake from the restored procession road; current evolution branches use level choices.</p>':'')+(state.storyFlags?.two_prayers_unlocked?'<h3>Two Prayers</h3><p>The first comparison is recorded in Cossenne. More accounts await in later towns.</p>':'')}</div><p class="bag-coin">Doubloons · ${state.money.toLocaleString('en-GB')}</p>`);document.querySelectorAll('[data-pocket]').forEach(el=>el.onclick=()=>bagMenu(el.dataset.pocket));document.querySelectorAll('[data-held-item]').forEach(b=>b.onclick=()=>heldTarget(b.dataset.heldItem));document.querySelectorAll('[data-evolve-ready]').forEach(b=>b.onclick=()=>queueEvolution([...state.party,...state.reserve].find(u=>u.uid===b.dataset.evolveReady)));document.querySelectorAll('[data-evolution-item]').forEach(b=>b.onclick=()=>evolutionItemTarget(b.dataset.evolutionItem));$('#bag-use-life-ember')?.addEventListener('click',lifeEmberTarget);document.querySelectorAll('[data-special-medicine]').forEach(el=>el.onclick=()=>specialistMedicineTarget(el.dataset.specialMedicine));$('#bag-use-poultice')?.addEventListener('click',medicineTarget);$('#bag-use-escort')?.addEventListener('click',useArmedEscort);$('#bag-use-binoculars')?.addEventListener('click',useBinoculars);$('#bag-use-evac')?.addEventListener('click',useEmergencyEvac);$('#use-training-tonic')?.addEventListener('click',trainingTonicTarget);document.querySelectorAll('[data-move-scroll]').forEach(el=>el.onclick=()=>moveScrollTarget(+el.dataset.moveScroll));menuBack();}
function medicineTarget(){openModal('Use a Poultice',`<p>Choose a living partner. You have ${state.poultices} Poultices.</p><div class="summary-list">${state.party.map(u=>`<button class="summary-choice" data-medicine-target="${u.uid}" ${!state.poultices||u.hp<=0||u.hp===u.maxHp?'disabled':''}><img src="${combatArtSrc(u)}" alt=""><span><b>${escapeHTML(unitName(u))}</b><small>${u.hp} / ${u.maxHp} HP</small></span><span>${u.hp<=0?'Cannot revive':u.hp===u.maxHp?'Full HP':'Restore up to '+Math.min(u.maxHp-u.hp,Math.floor(Math.min(50,Math.floor(u.maxHp/2))*healingMultiplier(u)))+' HP'}</span></button>`).join('')}</div>`);document.querySelectorAll('[data-medicine-target]').forEach(el=>el.onclick=()=>{const u=state.party.find(u=>u.uid===el.dataset.medicineTarget);if(!u||!state.poultices||u.hp<=0||u.hp>=u.maxHp)return;const oldHP=u.hp,oldCount=state.poultices,n=heal(u);if(!n)return;state.poultices--;if(!persist()){u.hp=oldHP;state.poultices=oldCount;medicineTarget();return;}refresh();bagMenu();toast(`${unitName(u)} recovered ${n} HP`);});menuBack(()=>bagMenu(),'Back to bag');}
function trainerMenu(){openModal('Trainer card',`<div class="trainer-card"><span class="eyebrow">CIVETON EXPEDITION</span><h3>${escapeHTML(state.playerName)}</h3><dl><div><dt>Location</dt><dd>${escapeHTML(roomName(room))}</dd></div><div><dt>Doubloons</dt><dd>${state.money.toLocaleString('en-GB')}</dd></div><div><dt>Active partners</dt><dd>${state.party.length} / 6</dd></div><div><dt>Reserve partners</dt><dd>${state.reserve.length}</dd></div><div><dt>Assessment</dt><dd>${state.test?'Passed':'Not yet passed'}</dd></div><div><dt>Taming lesson</dt><dd>${state.tamingTaught?'Completed':'Not yet completed'}</dd></div></dl><button id="trainer-rename">Change name</button></div>`);$('#trainer-rename').onclick=()=>namePrompt('Character name',state.playerName,name=>{state.playerName=name;persist();refresh();trainerMenu();});menuBack();}
