 openModal(c.title+' · mechanism',`<details class="repair-reading"><summary>Read the full repair note</summary>${campaignParagraphs(c.clues[1]).map(p=>'<p>'+escapeHTML(p)+'</p>').join('')}</details><p>${escapeHTML(c.puzzleClue)}</p><p>${escapeHTML(campaignControlHelp(c))}</p><p><b>${q.solved?'Route restored':stateText}</b></p><div class="modal-actions">${[0,1,2].map(n=>`<button data-sc-control="${n}" ${q.solved?'disabled':''}>${n+1} · ${escapeHTML(c.controlLabels[n])}</button>`).join('')}<button id="sc-reset" ${q.solved?'disabled':''}>Reset mechanism</button></div>${!q.solved&&campaignAffinity(state,c)?`<button id="sc-assist">Ask a ${c.affinity}-type partner to help</button>`:''}`);
