function stormFollowup(){
 const q=stormState(state).darius,encounter=stormDragonEncounter(state);if(!q.followupPending)return;
 if(!encounter){rewardTransaction(()=>{q.followupPending=false;});return;}
 showDialogue([line('Storm Crown','The grounding tether snaps. Tianzhar rises behind Darius, filling the tower with cold light. It turns away from his outstretched hand.'),line('Darius','I only wanted them to stop. Please. I only wanted them to stop.','REV-DARIUS-STORM'),line('Storm Crown','The sovereign lowers its crown towards you. Thunder answers from every conductor.')],()=>{startWild(encounter);if(battle?.stormId==='tianzhar')rewardTransaction(()=>{q.followupPending=false;});});
}

// Real-world finale: saved scene cursor, personal legacies, two cities and the last company.
let finaleSceneBusy=false;
const finaleCreatureImages=new Map();
function getFinaleCreatureImage(u){const key=u.species.id+':'+Boolean(u.shiny);if(!finaleCreatureImages.has(key)){const im=new Image();finaleCreatureImages.set(key,im);void combatArtReady(u).then(()=>{im.src=combatArtSrc(u);});}return finaleCreatureImages.get(key);}
function clearFinaleScene(){document.querySelector('#finale-story')?.remove();$('#dialogue').classList.remove('finale-story-dialogue');}
function showFinaleScene(name){clearFinaleScene();const panel=document.createElement('div');panel.id='finale-story';panel.style.backgroundImage=`url(assets/finale/story-${name==='burial'?'burial':'darius-cruxwyrm'}.webp)`;panel.setAttribute('role','img');panel.setAttribute('aria-label',name==='burial'?'Aimon and Walter bury Pate and Trade beneath the flowering tree':'Darius and Cruxwyrm hold the last crossing');$('#viewport').append(panel);$('#dialogue').classList.add('finale-story-dialogue');}
function finaleAPI(){return {state,room,AREA_GATES,line,showDialogue,warp,rewardTransaction,buildMarkers,openModal,closeModal,escapeHTML,challengeTrainer,startWild,species:byId,$,rest:restAtPriest,art:combatArtSrc,create:(id,level,seed)=>newUnit(byId(id),level,seed),settleLeaderRewards,decisionHTML:leaderDecisionHTML,burial:playFinaleBurial,doubleBattle:startFinaleDouble,scene:showFinaleScene,clearScene:clearFinaleScene,rematch:t=>{registerLeaderRematches();const r=EXPANSION.trainers.find(r=>r.rematchOf===t.id);if(r)challengeTrainer(r);}};}
function finaleInteract(id){return handleFinale(id,finaleAPI());}
function playFinaleBurial(){const q=finaleState(state);if(finaleSceneBusy||q.buried||!BURIAL_LINES[q.burialCursor])return;finaleSceneBusy=true;showFinaleScene('burial');const index=q.burialCursor,args=BURIAL_LINES[index];showDialogue([line(args[0],args[1])],()=>{if(!rewardTransaction(()=>{finishBurialLine(state,index);if(finaleState(state).buried)grantMemorialPartners(state,(id,level,seed)=>newUnit(byId(id),level,seed));})){finaleSceneBusy=false;clearFinaleScene();return;}finaleSceneBusy=false;if(q.buried){clearFinaleScene();buildMarkers();const units=Object.values(q.legacies).map(r=>[...state.party,...state.reserve].find(u=>u.uid===r.uid)).filter(Boolean);openModal('Their travelling companions',`<p>Two friends join the road with you. Both have a permanent +15 percentage points in every growth rate. Their lives are now in your care.</p><div class="finale-legacy-pair">${units.map(u=>`<article><img src="${combatArtSrc(u)}" alt="${escapeHTML(u.species.name)}"><h3>${escapeHTML(u.species.name)}</h3><p>Lv. ${u.level} · ${escapeHTML(u.giftOrigin)}</p><small>${state.party.includes(u)?'Joined your expedition':'Waiting safely in reserve'}</small></article>`).join('')}</div><button id="fn-legacy-continue" class="primary">Continue together</button>`);$('#fn-legacy-continue').onclick=closeModal;}});}
function startFinaleDouble(){clearFinaleScene();if(battle||presentationLocked||!lead()||!canFightFinale(state,'TRN-FN-DARIUS'))return;const before=wildCheckpoint(),q=finaleState(state),p=lead();presentationHealth=null;q.specimens??={};const ally=newUnit(byId('071'),103,'finale-hasan-serapine');ally.combatFloor=1;const enemies=FINAL_DARIUS.team.map((slot,i)=>{let u=i===0&&q.specimens.crux?hydrate(structuredClone(q.specimens.crux)):newUnit(byId(slot.species_id),slot.level,i===0?'finale-unique-crux':'darius-final-'+i);u.moves=slot.current_form_legal_move_ids.filter(id=>moveId(id)?.category).slice(-4).map(id=>({...moveId(id),left:moveId(id).pp}));u.hp=u.maxHp;u.status=null;u.stages={};u.dead=false;u.side='enemy';u.combatFloor=0;delete u.withdrawn;if(i===0){q.specimens.crux??=structuredClone(u);u.boundSovereign=true;u.combatFloor=1;}return u;});battle={kind:'wild',relicDouble:true,finaleDouble:true,alliedRivet:ally,participants:[p.uid],defeats:[],player:p,enemies,activeEnemyIndices:[0,1],reserveCursor:2,index:0,targetIndex:0,total:6,round:1,random:rng(Math.floor(worldRandom()*0xffffffff)||1),busy:true,finished:false,artReady:false,phase:'ready',history:[],log:'Hasan stands beside you. Choose one of the two active opponents; enemy reserves enter between rounds.'};const field={};p.combatFloor=0;beginAbilities(p,enemies.slice(0,2),[...state.party,ally],field);enterAbility(ally,enemies[0],{party:[...state.party,ally],field});bindMenagerieParty(state.party);if(!persist()){rollbackWild(before);return;}showBattleSurface();renderBattle();const b=battle;void battleArtReady(p,ally,...enemies).then(()=>{if(battle!==b)return;b.artReady=true;b.busy=false;renderBattle();persist();});}
async function finishFinaleDouble(outcome){const b=battle;if(!b?.finaleDouble)return;b.finished=true;b.busy=true;if(modal)closeModal();if(outcome==='defeated'){if(!b.finaleGranted){const previous=b.finaleGranted;if(!rewardTransaction(()=>{if(settleDariusFinale(state))state.money+=18000;b.finaleGranted=true;})){b.finaleGranted=previous;rewardSaveRetry(()=>{modal=false;$('#modal-root').innerHTML='';void finishFinaleDouble(outcome);});return;}}if(!commitRewards(b,b.defeats,{kind:'finale-double'})){rewardSaveRetry(()=>{modal=false;$('#modal-root').innerHTML='';void finishFinaleDouble(outcome);});return;}}else{if([...state.party,...state.reserve,...state.dead].some(u=>u.trainingEffects?.length)&&!closeTrainingBattle(b))return;if(state.binocularBattles>0&&!closeBinocularBattle(b))return;}hideBattleSurface();encounterGrace=3;trainerGrace=performance.now()+3000;refresh();buildMarkers();persist();if(outcome==='defeated')showRewards();else if(outcome==='wipe')expeditionRecovery();else toast('Hasan covers your retreat. Prepare before returning to the crossing.');}
function finaleDariusFollowup(){const q=finaleState(state);if(!q.dariusFollowup||dialogue||battle||modal)return;showDialogue([line('Sporefall','Darius reaches for another command. Cruxwyrm turns away. Soldiers from both companies move past him to help the wounded.'),line('Darius','If they go back, it starts again. Don’t you understand?','REV-DARIUS-FINAL'),line('Hasan','I understand that those people are still alive. They are coming off this bridge.','LDR-08'),line('Sporefall','With his company beaten, Darius is disarmed and taken into the joint companies’ custody. This time he leaves under guard. Cruxwyrm remains by the broken span.'),line('Hasan','Come to Ramelle when you are ready. Face me there, under proper terms. Then I will show you the door beneath my fortress.','LDR-08'),line('Aimon','You know about it.','CHR-AIMON'),line('Hasan','I know where it is. What you will hear from it is another matter.','LDR-08')],()=>{rewardTransaction(()=>{q.dariusFollowup=false;});buildMarkers();});}

